/**
 * Theo UI — Theme types.
 *
 * A Theme is a frozen bundle of CSS-var values that the runtime can swap by
 * setting `data-theme="<name>"` on `<html>`. The structure mirrors what lives
 * in tokens.css so themes can be merged without ambiguity.
 */

export type ThemeMode = "light" | "dark";

export interface ColorScale {
  background: string;
  foreground: string;
  card: string;
  "card-foreground": string;
  popover: string;
  "popover-foreground": string;
  primary: string;
  /**
   * Tonal scale variants of `primary`. Optional since T3.2 (ADR-0006).
   * When omitted, derived in CSS from `--primary` via `oklch(from ...)`.
   * Override per-theme by providing an explicit string.
   */
  "primary-deep"?: string;
  "primary-glow"?: string;
  "primary-foreground": string;
  secondary: string;
  "secondary-foreground": string;
  accent: string;
  /**
   * Tonal scale variant of `accent`. Optional since T3.2 — derived in CSS
   * when omitted. Override per-theme by providing an explicit string.
   */
  "accent-deep"?: string;
  "accent-foreground": string;
  muted: string;
  "muted-foreground": string;
  border: string;
  input: string;
  ring: string;
  success: string;
  "success-foreground": string;
  warning: string;
  "warning-foreground": string;
  destructive: string;
  "destructive-foreground": string;
  info: string;
  "info-foreground": string;
  /**
   * Status semantic group (D4 ADR — community-best-practices plan).
   *
   * Operational state colors (gateway connected/disconnected/slow/info-flag)
   * separated from action-result semantics (success/destructive/warning/info).
   * Defaults in built-in themes mirror their semantic counterparts; consumers
   * may override for visually-distinct status surfaces. `defineTheme(partial)`
   * auto-populates from semantic group when omitted.
   */
  "status-online": string;
  "status-online-foreground": string;
  "status-offline": string;
  "status-offline-foreground": string;
  "status-degraded": string;
  "status-degraded-foreground": string;
  "status-info": string;
  "status-info-foreground": string;
}

export interface ThemeFonts {
  /** Display headlines (h1-h3, hero text). */
  display: string;
  /** Body / UI text. */
  body: string;
  /** Code, mono, paths, timestamps. */
  mono: string;
}

/**
 * The corner radii a theme may set.
 *
 * Every key is optional and only what is present is emitted, so a theme that says nothing about
 * shape inherits the scale in `tokens.css` untouched — the same rule the colour scale follows for
 * its own optional tonal variants.
 *
 * Values are CSS lengths (`0px`, `0.5rem`, `9999px`). They reach the page as `--radius-*`, which
 * the Tailwind `@theme` namespace defers to, so setting one moves every `rounded-*` utility at
 * paint time (usetheokit/theokit-ui#88).
 */
export interface RadiusScale {
  none?: string;
  sm?: string;
  md?: string;
  lg?: string;
  xl?: string;
  "2xl"?: string;
  full?: string;
  /** The shadcn-compatible `--radius`, which components read when they want "the" radius. */
  DEFAULT?: string;
}

/**
 * The elevation a theme may set.
 *
 * Shadows in `tokens.css` are composed from `--foreground` via `color-mix`, so they already follow
 * a palette change. Setting one here replaces that composition outright — useful for a flat theme
 * (`sm: "none"`) or a heavier one, and the reason to reach for it is a different elevation
 * *language*, not a different colour.
 */
export interface ShadowScale {
  sm?: string;
  md?: string;
  lg?: string;
  glow?: string;
  "glow-strong"?: string;
}

/**
 * The motion a theme may set: three durations and three easings.
 *
 * A theme that wants to feel brisk or deliberate changes these rather than every transition in
 * every component. `prefers-reduced-motion` is handled in `global.css` and is not affected by what
 * a theme declares here — a theme cannot re-enable motion for someone who asked for less.
 */
/**
 * The named spacing steps.
 *
 * Separate from `spacing`, which is the base every `p-*`/`gap-*` utility multiplies. These are the
 * fixed rungs a consumer reads directly — `var(--space-6)` in their own CSS — and nothing inside
 * this package uses them, which is exactly why they belong here: a token that only a consumer reads
 * is a token only a consumer can be surprised by.
 */
export interface SpaceScale {
  1?: string;
  2?: string;
  3?: string;
  4?: string;
  5?: string;
  6?: string;
  8?: string;
  10?: string;
  12?: string;
  16?: string;
  20?: string;
  24?: string;
  32?: string;
}

export interface MotionScale {
  "duration-fast"?: string;
  "duration-base"?: string;
  "duration-slow"?: string;
  "ease-out-soft"?: string;
  "ease-snap"?: string;
  "ease-in-out"?: string;
  /** Delay between items in a staggered sequence. `prefers-reduced-motion` zeroes it regardless. */
  stagger?: string;
}

export interface Theme {
  /** Stable id, used in `data-theme`. */
  name: string;
  /** Human-readable label for theme switchers. */
  label: string;
  /** Optional short description shown in switchers. */
  description?: string;
  fonts: ThemeFonts;
  light: ColorScale;
  dark: ColorScale;
  /**
   * Optional URL(s) to fetch before applying. The provider injects a `<link>`
   * tag once per URL to load remote fonts. Already-injected URLs are deduped.
   */
  fontUrls?: string[];
  /**
   * Corner radii. Omitted keys keep the scale from `tokens.css`.
   *
   * Shape is not mode-dependent the way colour is — a rounder theme is rounder in both — so these
   * sit beside `light`/`dark` rather than inside them.
   */
  radius?: RadiusScale;
  /**
   * The spacing base. Every `p-*`, `gap-*` and `m-*` utility is `calc(var(--spacing) * n)`, so one
   * value scales the whole rhythm — `"3px"` tightens the entire UI, `"5px"` loosens it.
   */
  spacing?: string;
  /** Elevation. Omitted keys keep the palette-derived shadows from `tokens.css`. */
  shadows?: ShadowScale;
  /** The named spacing steps a consumer reads directly. Omitted keys keep the defaults. */
  space?: SpaceScale;
  /** Durations and easings. Omitted keys keep the defaults. */
  motion?: MotionScale;
}

/**
 * Theme color value validation pattern — Phase 2 T2.5, EC-5 absorbed.
 *
 * Allowed forms (one or more, single string per token):
 *   1. Hex:        `#fff`, `#0a0a0a`, `#0a0a0aff`
 *   2. CSS color functions:
 *      - oklch/oklab: supports relative-color syntax `oklch(from var(--x) l c h)`,
 *        `calc(...)` of depth 1, `none` keyword, and single-char component
 *        identifiers (`l`, `c`, `h`, `a`, `b`).
 *      - rgb, rgba, hsl, hsla, lab, lch, color: conservative content
 *        `[\d.\s%,/+\-]+` — no nested function calls.
 *   3. HSL split tuple (legacy ColorScale convention pre-T2.4):
 *      `"0 0% 100%"`, `"262 83% 58%"` — space-separated numeric components.
 *   4. `var(--token)` reference with optional safe fallback value.
 *   5. CSS keywords: `transparent`, `currentColor`, `inherit`, `initial`, `unset`.
 *
 * Defense in depth: rejects values that contain `;`, `{`, `}`, `url(` — the
 * vectors used to break out of the CSS declaration injected by ThemeProvider.
 * `oklch(from ...)` permits a single bare var() identifier and at most ONE
 * level of nested `calc(...)` to keep the surface scoped.
 */

// OKLCH/oklab relative-color or static form.
// Allows: `oklch(0.5 0.2 270)`, `oklch(0.5 0.2 270 / 0.5)`,
//         `oklch(from var(--primary) calc(l - 0.16) c h)`,
//         `oklch(none none none)`, `oklch(from var(--x) l c h / 0.5)`.
const OKLCH_RELATIVE_OR_STATIC =
  String.raw`(?:oklch|oklab)\(\s*` +
  // Optional `from var(--token)` prefix.
  String.raw`(?:from\s+var\(--[a-zA-Z0-9-]+\)\s+)?` +
  // 1+ component tokens: calc(no-nested) | single letter | numeric | `none` | `/`.
  // max()/min() may wrap a calc(); calc() itself stays flat. Single nesting depth.
  String.raw`(?:max\([^(){}]*(?:\([^(){}]*\))?[^(){}]*\)|min\([^(){}]*(?:\([^(){}]*\))?[^(){}]*\)|calc\([^();{}]+\)|[a-z]|-?\d+(?:\.\d+)?%?|none|\/|\s)+` +
  String.raw`\)`;

// Other CSS color functions — conservative content (no nested parens/words).
const CONSERVATIVE_COLOR_FN = String.raw`(?:rgb|rgba|hsl|hsla|lab|lch|color)\(\s*[\d.\s%,/+\-]+\s*\)`;

const HEX = String.raw`#[0-9a-fA-F]{3,8}`;

// HSL split: "H S% L%" or "H S L" (legacy ColorScale convention).
const HSL_SPLIT = String.raw`-?\d+(?:\.\d+)?%?(?:\s+-?\d+(?:\.\d+)?%?){1,3}`;

const VAR_REF = String.raw`var\(--[a-zA-Z0-9-]+(?:\s*,\s*[^();{}]+)?\)`;

const KEYWORDS = String.raw`transparent|currentColor|inherit|initial|unset`;

export const COLOR_VALUE_PATTERN = new RegExp(
  `^(${HEX}|${OKLCH_RELATIVE_OR_STATIC}|${CONSERVATIVE_COLOR_FN}|${HSL_SPLIT}|${VAR_REF}|${KEYWORDS})$`,
);

"use client";

/**
 * `useDensity()` — runtime control of the global UI density.
 *
 * FAANG-modern dashboards (Vercel / Linear / Stripe) ship at "comfortable"
 * density: form controls at 36px, body text 14px, card padding 20px. For
 * dense surfaces (data tables, agent tool lists, admin grids) `compact` mode
 * tightens form controls to 32px without touching `sm`/`lg` props the
 * consumer already passed. Spacious mode bumps the default up to 44px for
 * accessibility-first surfaces.
 *
 * Mechanism (EC-1 fix from edge-case review 2026-05-22):
 *   - ThemeProvider sets `data-density="{value}"` on `<html>`.
 *   - A `<style id="theo-ui-density-vars">` block defines CSS custom
 *     properties under each `[data-density=...]` selector:
 *       --theo-control-h, --theo-control-px
 *   - Form-control `cva` variants for the `md` tier read from these vars:
 *       `md: "h-[var(--theo-control-h,2.25rem)] px-[var(--theo-control-px,0.875rem)] text-body-sm"`
 *   - `sm` and `lg` variants stay hardcoded → explicit `size` prop always
 *     wins over density.
 *
 * RFC: `wiki/rfcs/0006-density-faang.md`.
 */
import { createContext, useContext } from "react";

export type Density = "compact" | "comfortable" | "spacious";

export interface DensityContextValue {
  density: Density;
  setDensity: (next: Density) => void;
}

export const DensityContext = createContext<DensityContextValue | undefined>(undefined);

const STYLE_ELEMENT_ID = "theo-ui-density-vars";

const DENSITY_CSS = `[data-density="compact"]     { --theo-control-h: 2rem;    --theo-control-px: 0.75rem; }
[data-density="comfortable"] { --theo-control-h: 2.25rem; --theo-control-px: 0.875rem; }
[data-density="spacious"]    { --theo-control-h: 2.75rem; --theo-control-px: 1rem; }
`;

/**
 * Inject (idempotent) the density CSS variable definitions into the document
 * head. Returns true if the style tag was newly created. Safe to call on
 * every ThemeProvider mount — duplicates are skipped.
 */
export function injectDensityCss(): boolean {
  if (typeof document === "undefined") return false;
  if (document.getElementById(STYLE_ELEMENT_ID)) return false;
  const style = document.createElement("style");
  style.id = STYLE_ELEMENT_ID;
  style.textContent = DENSITY_CSS;
  document.head.appendChild(style);
  return true;
}

/**
 * Read the current density from the active ThemeProvider context. Throws
 * outside the provider so misuse fails loud — analogous to `useTheme`.
 */
export function useDensity(): DensityContextValue {
  const ctx = useContext(DensityContext);
  if (!ctx) {
    throw new Error("useDensity must be used inside <ThemeProvider>.");
  }
  return ctx;
}

/**
 * Valibot schema for Theme — Phase 2 T2.7 / D5 (revised post-EC-6).
 *
 * Validates the shape and types of a Theme object passed to <ThemeProvider>
 * or registerTheme(). Complements the COLOR_VALUE_PATTERN regex (the second
 * defense layer against CSS injection): valibot validates shape; regex
 * validates that each individual color value is safe to interpolate.
 *
 * Why valibot (not zod): valibot core is ~1.5KB gzipped vs zod ~12KB.
 * <ThemeProvider> is a sync constructor — dynamic import does not tree-shake.
 * For our use case (validating ~37 string fields) valibot is strictly
 * better in bundle size and API parity.
 *
 * Output of safeParse → { success: true, output } or { success: false, issues }.
 * formatThemeIssues() produces human-readable error message with the failing
 * field path so consumers see what to fix.
 */

import * as v from "valibot";

import { COLOR_VALUE_PATTERN } from "@/themes/color-value-pattern";

const THEME_NAME_PATTERN = /^[a-z][a-z0-9-]*$/;
const FONT_FAMILY_PATTERN = /^[\w\s,"'\-.]+$/;

const colorValueSchema = v.pipe(
  v.string(),
  v.check(
    (value) => COLOR_VALUE_PATTERN.test(value),
    "color value did not match the allowed format (hex, oklch, hsl, rgb, var(), HSL split, or CSS keyword)",
  ),
);

const themeNameSchema = v.pipe(
  v.string(),
  v.check(
    (value) => THEME_NAME_PATTERN.test(value),
    "theme name must match /^[a-z][a-z0-9-]*$/ (lowercase + digits + hyphens, starts with a letter)",
  ),
);

const fontFamilySchema = v.pipe(
  v.string(),
  v.check(
    (value) => FONT_FAMILY_PATTERN.test(value),
    "font family contains disallowed characters (parens, semicolons, etc.)",
  ),
);

const fontsSchema = v.object({
  display: fontFamilySchema,
  body: fontFamilySchema,
  mono: fontFamilySchema,
});

// All 37 ColorScale keys (29 base + 8 status — D4).
const colorScaleSchema = v.object({
  background: colorValueSchema,
  foreground: colorValueSchema,
  card: colorValueSchema,
  "card-foreground": colorValueSchema,
  popover: colorValueSchema,
  "popover-foreground": colorValueSchema,
  primary: colorValueSchema,
  // Optional since T3.2 (ADR-0006) — CSS derives via oklch(from var(--primary) ...).
  "primary-deep": v.optional(colorValueSchema),
  "primary-glow": v.optional(colorValueSchema),
  "primary-foreground": colorValueSchema,
  secondary: colorValueSchema,
  "secondary-foreground": colorValueSchema,
  accent: colorValueSchema,
  "accent-deep": v.optional(colorValueSchema),
  "accent-foreground": colorValueSchema,
  muted: colorValueSchema,
  "muted-foreground": colorValueSchema,
  border: colorValueSchema,
  input: colorValueSchema,
  ring: colorValueSchema,
  success: colorValueSchema,
  "success-foreground": colorValueSchema,
  warning: colorValueSchema,
  "warning-foreground": colorValueSchema,
  destructive: colorValueSchema,
  "destructive-foreground": colorValueSchema,
  info: colorValueSchema,
  "info-foreground": colorValueSchema,
  "status-online": colorValueSchema,
  "status-online-foreground": colorValueSchema,
  "status-offline": colorValueSchema,
  "status-offline-foreground": colorValueSchema,
  "status-degraded": colorValueSchema,
  "status-degraded-foreground": colorValueSchema,
  "status-info": colorValueSchema,
  "status-info-foreground": colorValueSchema,
});

export const themeSchema = v.object({
  name: themeNameSchema,
  label: v.string(),
  description: v.optional(v.string()),
  fonts: fontsSchema,
  light: colorScaleSchema,
  dark: colorScaleSchema,
  fontUrls: v.optional(
    v.array(
      v.pipe(
        v.string(),
        v.url(),
        v.check(
          (value) => /^https?:\/\//i.test(value),
          "fontUrls must use http(s) protocol (javascript:, data:, etc. are rejected)",
        ),
      ),
    ),
  ),
});

export type ThemeIssue = v.InferIssue<typeof themeSchema>;

export interface ThemeValidationResult {
  success: boolean;
  issues?: ThemeIssue[];
}

export function validateTheme(theme: unknown): ThemeValidationResult {
  const result = v.safeParse(themeSchema, theme);
  if (result.success) return { success: true };
  return { success: false, issues: result.issues };
}

export function formatThemeIssues(themeName: string, issues: ThemeIssue[]): string {
  const lines: string[] = [`[@theokit/ui] theme '${themeName}' failed validation:`];
  for (const issue of issues) {
    const path = (issue.path ?? [])
      .map((segment) => (typeof segment.key === "string" ? segment.key : String(segment.key)))
      .join(".");
    lines.push(`  - ${path || "(root)"}: ${issue.message}`);
  }
  return lines.join("\n");
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { JSX, ReactNode } from "react";
import { isDev } from "@/lib/env";
import { safeHref } from "@/lib/safe-href";
import { COLOR_VALUE_PATTERN } from "@/themes/color-value-pattern";
import { type Density, DensityContext, injectDensityCss } from "@/themes/density";
import { formatThemeIssues, validateTheme } from "@/themes/schema";
import type { ColorScale, Theme, ThemeMode } from "@/themes/types";

interface ThemeContextValue {
  /** Active theme (full descriptor). */
  theme: Theme;
  /** Active mode: light or dark. */
  mode: ThemeMode;
  /** All available themes. */
  themes: Theme[];
  /** Swap the active theme by name. */
  setTheme: (name: string) => void;
  /** Set light/dark explicitly. */
  setMode: (mode: ThemeMode) => void;
  /** Toggle light <> dark. */
  toggleMode: () => void;
  /** Register an additional theme at runtime. */
  registerTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const STYLE_ELEMENT_ID = "theo-ui-theme-vars";

// T3.2 (SEC-001): allowlist validators for theme values. injectThemeCss
// interpolates theme name + color values + font families into a <style>
// textContent. Without validation, a theme object from an untrusted source
// (e.g., a feature-flag service, a CMS) could inject arbitrary CSS via
// closing the declaration with `}` or smuggling `url(...)` for exfiltration.
// We reject rather than escape: themes are code, not user input. Invalid
// values cause a dev-time throw (caller sees the problem); production
// silently substitutes a safe fallback so a misconfigured theme can't
// crash the app.

// COLOR_VALUE_PATTERN was inlined here pre-T2.5. Now extracted to
// `color-value-pattern.ts` so the regex is reusable by the Valibot schema (T2.7)
// and so the OKLCH relative-color syntax (`oklch(from var(--x) calc(l - 0.16) c h)`,
// required by T3.1 tonal derivations) is supported without expanding the inline
// regex monolith. See EC-5 in the edge-case review.

// Font family: word chars, spaces, commas, hyphens, dots, quotes. Excludes
// parens (blocks `url(...)`) and semicolons (blocks declaration breakouts).
const FONT_FAMILY_PATTERN = /^[\w\s,"'\-.]+$/;

// Theme name: kebab-case identifier. Excludes anything that could break out
// of an attribute selector or inject additional rules.
const THEME_NAME_PATTERN = /^[a-z][a-z0-9-]*$/;

// A CSS length or unitless zero, optionally wrapped in calc()/min()/max()/clamp() over the same.
// Covers what a radius, a spacing base or a duration can be. Excludes semicolons and braces (which
// would break out of the declaration) and `url(` (which would exfiltrate), on the same reasoning
// as the colour allowlist above: themes are code, but a theme object can arrive from a CMS.
const LENGTH_PATTERN =
  /^(?:0|calc|min|max|clamp|[\d.]+(?:px|rem|em|%|vh|vw|vmin|vmax|s|ms|ch|ex))[\w\s%.,()+*/-]*$/;

// A shadow is a list of offsets and colours, so it admits far more than a length — but the same
// two exclusions apply, and they are what the pattern is for.
const SHADOW_PATTERN = /^(?!.*url\()[^;{}<>]+$/;

// An easing: a keyword or a cubic-bezier()/steps()/linear() function over numbers.
const EASING_PATTERN =
  /^(?:linear|ease|ease-in|ease-out|ease-in-out|step-start|step-end|cubic-bezier\([\d\s.,-]+\)|steps\([\d\s,a-z-]+\)|linear\([\d\s%.,-]+\))$/;

const IS_DEV = isDev();

function rejectOrFallback(scope: string, value: string, fallback: string): string {
  if (IS_DEV) {
    throw new Error(
      `[@theokit/ui] invalid ${scope} value: ${JSON.stringify(value)}. Theme values must match the allowlist (see src/themes/theme-provider.tsx). Refusing to inject potentially unsafe CSS.`,
    );
  }
  return fallback;
}

function validatedColor(token: string, value: string): string {
  if (COLOR_VALUE_PATTERN.test(value)) return value;
  return rejectOrFallback(`color "${token}"`, value, "transparent");
}

function validatedFontFamily(slot: string, value: string): string {
  if (FONT_FAMILY_PATTERN.test(value)) return value;
  return rejectOrFallback(`fontFamily "${slot}"`, value, "inherit");
}

function validatedThemeName(value: string): string {
  if (THEME_NAME_PATTERN.test(value)) return value;
  return rejectOrFallback("theme.name", value, "invalid-theme");
}

function validatedLength(token: string, value: string): string {
  if (LENGTH_PATTERN.test(value)) return value;
  return rejectOrFallback(`length "${token}"`, value, "0px");
}

function validatedShadow(token: string, value: string): string {
  if (value === "none" || SHADOW_PATTERN.test(value)) return value;
  return rejectOrFallback(`shadow "${token}"`, value, "none");
}

function validatedEasing(token: string, value: string): string {
  if (EASING_PATTERN.test(value)) return value;
  return rejectOrFallback(`easing "${token}"`, value, "ease");
}

function colorScaleToCss(name: string, mode: ThemeMode, colors: ColorScale): string {
  const safeName = validatedThemeName(name);
  const selector =
    mode === "light"
      ? `[data-theme="${safeName}"]`
      : `[data-theme="${safeName}"].dark, [data-theme="${safeName}"][data-mode="dark"]`;
  const decls = Object.entries(colors)
    .map(([token, value]) => `  --${token}: ${validatedColor(token, value)};`)
    .join("\n");
  return `${selector} {\n${decls}\n}`;
}

function fontsToCss(name: string, fonts: Theme["fonts"]): string {
  const safeName = validatedThemeName(name);
  const display = validatedFontFamily("display", fonts.display);
  const body = validatedFontFamily("body", fonts.body);
  const mono = validatedFontFamily("mono", fonts.mono);
  return `[data-theme="${safeName}"] {\n  --font-display: ${display};\n  --font-body: ${body};\n  --font-mono: ${mono};\n}`;
}

/**
 * The non-colour half of a theme: radii, spacing base, elevation and motion.
 *
 * Emitted from one selector and only for the keys a theme actually declares, so a theme that says
 * nothing about shape adds no declarations and `tokens.css` stands. Unlike colour, none of this is
 * mode-dependent — a rounder theme is rounder in both modes — so there is a single block rather
 * than a light and a dark one.
 *
 * Returns an empty string when there is nothing to say, and the caller drops it: an empty rule in
 * the injected sheet is noise for anyone reading the page's styles.
 */
function shapeToCss(theme: Theme): string {
  const safeName = validatedThemeName(theme.name);
  const decls: string[] = [];

  for (const [key, value] of Object.entries(theme.radius ?? {})) {
    if (typeof value !== "string") continue;
    const token = key === "DEFAULT" ? "--radius" : `--radius-${key}`;
    decls.push(`  ${token}: ${validatedLength(token, value)};`);
  }

  if (typeof theme.spacing === "string") {
    decls.push(`  --spacing: ${validatedLength("--spacing", theme.spacing)};`);
  }

  for (const [key, value] of Object.entries(theme.space ?? {})) {
    if (typeof value !== "string") continue;
    const token = `--space-${key}`;
    decls.push(`  ${token}: ${validatedLength(token, value)};`);
  }

  for (const [key, value] of Object.entries(theme.shadows ?? {})) {
    if (typeof value !== "string") continue;
    decls.push(`  --shadow-${key}: ${validatedShadow(`--shadow-${key}`, value)};`);
  }

  for (const [key, value] of Object.entries(theme.motion ?? {})) {
    if (typeof value !== "string") continue;
    const isEasing = key.startsWith("ease");
    const token = `--${key}`;
    const safe = isEasing ? validatedEasing(token, value) : validatedLength(token, value);
    decls.push(`  ${token}: ${safe};`);
  }

  if (decls.length === 0) return "";
  return `[data-theme="${safeName}"] {\n${decls.join("\n")}\n}`;
}

function injectThemeCss(themes: Theme[]): void {
  if (typeof document === "undefined") return;
  let style = document.getElementById(STYLE_ELEMENT_ID) as HTMLStyleElement | null;
  if (!style) {
    style = document.createElement("style");
    style.id = STYLE_ELEMENT_ID;
    document.head.appendChild(style);
  }
  const blocks: string[] = [];
  for (const theme of themes) {
    blocks.push(fontsToCss(theme.name, theme.fonts));
    const shape = shapeToCss(theme);
    if (shape !== "") blocks.push(shape);
    blocks.push(colorScaleToCss(theme.name, "light", theme.light));
    blocks.push(colorScaleToCss(theme.name, "dark", theme.dark));
  }

  /**
   * Wrapped in `@layer theme` — the same layer `tokens.css` uses, and the first of the
   * canonical order this package declares.
   *
   * This block is injected at the end of `<head>`, so unlayered it would outrank anything the
   * consumer writes, at any specificity: applying a theme would silently disable their ability
   * to adjust a single token on top of it. That is the second half of
   * usetheokit/theokit-ui#72 — the first half being the same problem in `tokens.css`.
   *
   * Inside the layer, the precedence reads the way a consumer expects: our defaults, then the
   * active theme, then whatever they wrote. The layer statement is repeated here because this
   * element can be the first stylesheet to register `theme` in a page that lazy-loads the CSS,
   * and a layer's position is fixed at its first appearance (see layer-order.test.ts / #20).
   */
  style.textContent = `@layer theme, base, components, utilities;\n\n@layer theme {\n${blocks.join("\n\n")}\n}`;
}

/**
 * loadThemeFonts — idempotently inject `<link rel="stylesheet">` for each
 * font URL declared by the theme.
 *
 * T4.2: the previous implementation kept a module-level `Set` to track
 * already-injected URLs. That singleton broke test isolation (state
 * leaked across renders) and silently skipped injection in micro-frontend
 * setups with multiple `<ThemeProvider>` mounts. Replaced with a DOM
 * check: we query `document.head` for an existing link with the same
 * `href` before appending a new one. The DOM is the single source of
 * truth; no shared state across instances.
 */
function loadThemeFonts(theme: Theme): void {
  if (typeof document === "undefined") return;
  if (!theme.fontUrls) return;
  for (const url of theme.fontUrls) {
    // Re-audit NEW-001 (SSRF, LOW): defang dangerous protocols on
    // consumer-provided font URLs. Built-in themes use
    // fonts.googleapis.com/gstatic.com — safe. registerTheme accepts
    // arbitrary objects at runtime; a malicious theme could try to inject
    // javascript:/data:text/html via fontUrls. safeHref returns undefined
    // for dangerous protocols, which we skip silently.
    const safe = safeHref(url);
    if (!safe) continue;
    if (document.head.querySelector(`link[rel="stylesheet"][href="${CSS.escape(safe)}"]`)) {
      continue;
    }
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = safe;
    document.head.appendChild(link);
  }
}

interface ThemeProviderProps {
  children: ReactNode;
  /**
   * Theme to start with. Must match the `name` of an entry in `themes`.
   * Defaults to `"violet-forge"` for backward compat — if you don't pass
   * `violet-forge` in `themes`, set this prop explicitly.
   */
  defaultTheme?: string;
  /** Mode to start with. Defaults to `"dark"` (library is dark-first). */
  defaultMode?: ThemeMode;
  /**
   * Available themes. **Required**: ThemeProvider does not auto-include any
   * built-in theme since v0.1.0-next.0 — pass `builtinThemes` for all three
   * Violet Forge defaults, or your own array for a slimmer bundle.
   *
   * Migration: consumers previously calling `<ThemeProvider>` without this
   * prop now must pass `themes={builtinThemes}` (or use `<TheoUIProvider>`
   * which defaults to `builtinThemes` for you).
   */
  themes: Theme[];
  /**
   * Persist selection in localStorage under this key. Pass `null` to disable.
   * Default: "theo-ui:theme".
   */
  storageKey?: string | null;
  /**
   * Initial density. Drives `data-density` on `<html>` and the `--theo-control-h`
   * / `--theo-control-px` CSS vars consumed by form-control `md` variants.
   * Defaults to `"comfortable"` (36px controls — FAANG-tier modern density).
   * Plan: faang-density-tightening (D3).
   */
  defaultDensity?: Density;
  /**
   * Respect the consumer's OS `prefers-color-scheme` preference on initial
   * mount (D6 / T5.1). When `true` (default) and no theme-mode is stored in
   * `localStorage[storageKey]`, the provider reads
   * `matchMedia('(prefers-color-scheme: dark)')` and subscribes to changes.
   * User-driven `setMode()` overrides the system signal — subsequent OS
   * changes are ignored after the user fixes a preference.
   *
   * Pass `false` to force `defaultMode` regardless of the system preference.
   * EC-12: matchMedia listener is cleaned up on unmount.
   */
  respectSystemMode?: boolean;
}

/**
 * Storage failure diagnostic — dev-only one-line warn so engineers see
 * something when localStorage throws (Safari private mode, blocked
 * third-party cookies, sandboxed iframes). In production we stay silent;
 * runtime behavior is fail-safe (state still lives in memory).
 *
 * Per HIGH-006: silent catches diverge from the "fail loud" principle
 * declared in the global CLAUDE.md. We accept silence in prod because the
 * fallback is correct, but we surface a single warn per call site in dev.
 */
function warnStorageFailure(scope: string, err: unknown): void {
  if (!isDev()) return;
  // biome-ignore lint/suspicious/noConsole: dev-only diagnostic for storage failures (HIGH-006)
  console.warn(`[@theokit/ui] theme storage failure (${scope}):`, err);
}

// T2.7: production-mode diagnostic for invalid themes that fall through
// dev-time throw. Single console.warn so engineer sees something instead of
// total silence; theme is kept in the array but per-value regex fallback
// substitutes `transparent` for unsafe values downstream.
function warnInvalidTheme(message: string): void {
  // biome-ignore lint/suspicious/noConsole: dev/prod diagnostic for invalid theme (T2.7/D5)
  console.warn(message);
}

/**
 * ThemeProvider — central registry + runtime switcher for Theo themes.
 *
 * Behavior:
 *   1. On mount, injects a `<style id="theo-ui-theme-vars">` element with
 *      one CSS block per theme (`[data-theme="<name>"] { --token: ... }`).
 *   2. Sets `data-theme` and `data-mode` on `<html>` so any element nested
 *      below inherits the right tokens (the Tailwind config consumes them).
 *   3. Lazy-loads theme font URLs by injecting `<link rel="stylesheet">`.
 *   4. Optionally persists choice in localStorage.
 */
function ThemeProvider({
  children,
  defaultTheme = "violet-forge",
  defaultMode = "dark",
  themes: themesProp,
  storageKey = "theo-ui:theme",
  defaultDensity = "comfortable",
  respectSystemMode = true,
}: ThemeProviderProps): JSX.Element {
  // Themes prop is required since v0.1.0-next.0 — see migration note in
  // the JSDoc on ThemeProviderProps. Pass `builtinThemes` for the legacy
  // default behavior (violet-forge + classic-paper + aurora-terminal), or
  // an array of your own. Empty array is rejected: ThemeProvider has no
  // valid state without at least one registered theme.
  if (!themesProp || themesProp.length === 0) {
    throw new Error(
      "<ThemeProvider> requires the `themes` prop with at least one Theme. " +
        "Pass `themes={builtinThemes}` for the Violet Forge defaults (importable " +
        "via the package barrel), or use <TheoUIProvider> which sets this for you.",
    );
  }

  // T3.2 (SEC-001): eager validation. Calling validatedColor/FontFamily/
  // ThemeName here ensures CSS-injection attempts throw at construction
  // time rather than inside the deferred useEffect that injects the
  // <style>. Production-mode fallbacks keep the app rendering even if a
  // theme has bad values.
  //
  // Re-audit NEW-3: wrapped in useMemo so the validation cost (O(themes *
  // tokens), ~60 ops per built-in theme) only runs when themesProp's
  // reference changes — not on every parent re-render. Consumers passing
  // inline array literals (`themes={[violetForge, classicPaper]}`) would
  // otherwise pay this on every parent update.
  const mergedThemes = useMemo<Theme[]>(() => {
    // T2.7 (D5): valibot shape validation runs FIRST — catches missing keys,
    // wrong types, malformed font URLs. Existing per-value regex validation
    // below stays as the second defense layer against CSS injection.
    for (const t of themesProp) {
      const result = validateTheme(t);
      if (!result.success) {
        const message = formatThemeIssues(
          (t as { name?: string }).name ?? "(unnamed)",
          result.issues ?? [],
        );
        if (IS_DEV) throw new Error(message);
        warnInvalidTheme(message);
        // In production we keep the theme array intact; the per-value regex
        // fallbacks below will substitute `transparent` for any value that
        // still fails the second layer, so the app continues rendering.
      }
    }
    for (const t of themesProp) {
      validatedThemeName(t.name);
      validatedFontFamily("display", t.fonts.display);
      validatedFontFamily("body", t.fonts.body);
      validatedFontFamily("mono", t.fonts.mono);
      for (const [token, value] of Object.entries(t.light)) {
        validatedColor(token, value);
      }
      for (const [token, value] of Object.entries(t.dark)) {
        validatedColor(token, value);
      }
    }
    // Dedup by theme name; last writer wins (allows registerTheme override).
    const map = new Map<string, Theme>();
    for (const t of themesProp) map.set(t.name, t);
    return Array.from(map.values());
  }, [themesProp]);

  const [themes, setThemes] = useState<Theme[]>(mergedThemes);

  // Re-sync state when the `themes` prop changes between renders. Avoids the
  // common pitfall where the user passes a different array later and the
  // initial-state-only seed silently ignores the change.
  useEffect(() => {
    setThemes(mergedThemes);
  }, [mergedThemes]);

  // SSR-safe initialization (0.6.3-next.0 hydration-mismatch fix).
  //
  // Previously: `useState(() => localStorage.getItem(…))`. The initializer
  // ran on BOTH server (no `window`, returned default) AND client at
  // hydration time (with `window`, returned the stored value). The two
  // results disagreed → React threw a hydration error on every page load
  // for any user who had previously changed themes, and re-rendered the
  // entire tree from scratch — defeating SSR.
  //
  // Fix: initialize with the SSR default ALWAYS. Promote to the stored
  // value in a post-mount `useEffect` below. The 1-frame visual flicker
  // is mitigated by the optional `<ThemeScript>` component, which sets
  // `data-theme` / `data-mode` / `data-density` on `<html>` before React
  // hydrates — see `theme-script.tsx`.
  //
  // The `hydratedRef` flag below guards the persist effect so that
  // first-mount writes (with the SSR default values) don't clobber the
  // user's stored preference in the brief window between mount and the
  // post-mount hydration effect.
  const [themeName, setThemeName] = useState<string>(defaultTheme);
  const [mode, setModeState] = useState<ThemeMode>(defaultMode);
  const [density, setDensityState] = useState<Density>(defaultDensity);

  // T5.1 / D6: track whether the user has explicitly fixed the mode via
  // setMode / toggleMode. Once true, OS prefers-color-scheme changes do
  // NOT override the user's choice.
  const userOverrodeModeRef = useRef(false);

  // First-run guard for the persist effect below. On initial mount the
  // state is the SSR-safe default; we MUST NOT clobber the user's stored
  // preference with that default before the post-mount hydration effect
  // can promote it. After the first persist-effect call returns early,
  // every subsequent change (post-hydration setState OR user-driven)
  // persists normally.
  const skipFirstPersistRef = useRef(true);

  // #116 — persistence is gated on an actual DECISION, not on a change.
  //
  // The provider's state changes for three reasons, and only one of them is a preference: the user
  // acting, the post-mount hydration promoting what was already stored, and the operating system's
  // `prefers-color-scheme`. The effect below used to write on all three, so a mode the OS chose
  // landed in storage — and on the next load the hydration effect reads it, sets
  // `userOverrodeModeRef`, and that OS-derived value then outranks the app's `defaultMode` and
  // survives `respectSystemMode={false}`, which is the very switch an app flips to stop this.
  const userDecidedRef = useRef(false);

  // Post-mount hydration: read localStorage and promote stored values to
  // state. Runs ONCE on mount. If `storageKey` is null or no value is
  // stored, this is a no-op — state stays at the SSR defaults.
  useEffect(() => {
    if (typeof window === "undefined" || !storageKey) return;
    try {
      const storedName = window.localStorage.getItem(`${storageKey}:name`);
      const storedMode = window.localStorage.getItem(`${storageKey}:mode`);
      const storedDensity = window.localStorage.getItem(`${storageKey}:density`);
      if (storedName) setThemeName(storedName);
      if (storedMode === "dark" || storedMode === "light") {
        setModeState(storedMode);
        // Stored value implies user fixed a preference at some point.
        userOverrodeModeRef.current = true;
      }
      if (
        storedDensity === "compact" ||
        storedDensity === "comfortable" ||
        storedDensity === "spacious"
      ) {
        setDensityState(storedDensity);
      }
    } catch (err) {
      warnStorageFailure("read theme + mode + density", err);
    }
  }, [storageKey]);

  // T5.1 / D6 / EC-12: subscribe to OS prefers-color-scheme when
  // respectSystemMode is true. On mount, if user has NOT overridden the
  // mode (no stored preference), align with the OS signal. Re-aligns on
  // OS changes UNLESS user explicitly fixed a preference. Cleanup on
  // unmount via removeEventListener (EC-12) to avoid listener leaks in
  // micro-frontend scenarios.
  useEffect(() => {
    if (!respectSystemMode) return;
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const mql = window.matchMedia("(prefers-color-scheme: dark)");
    // Align on first run if user hasn't overridden.
    if (!userOverrodeModeRef.current) {
      setModeState(mql.matches ? "dark" : "light");
    }
    const onChange = (event: MediaQueryListEvent): void => {
      if (!userOverrodeModeRef.current) {
        setModeState(event.matches ? "dark" : "light");
      }
    };
    mql.addEventListener("change", onChange);
    return () => {
      mql.removeEventListener("change", onChange);
    };
  }, [respectSystemMode]);

  // Inject CSS vars whenever the themes list changes.
  useEffect(() => {
    injectThemeCss(themes);
  }, [themes]);

  // Apply data-theme + data-mode + data-density to <html>, load fonts,
  // inject density CSS vars.
  useEffect(() => {
    if (typeof document === "undefined") return;
    const active = themes.find((t) => t.name === themeName) ?? themes[0];
    if (!active) return;
    // #116 — the `?? themes[0]` fallback used to apply one theme while state kept naming another,
    // so `useTheme().themeName` disagreed with `data-theme` and a theme switcher highlighted a
    // theme that was not on screen. Worse, the next user action persisted the name in STATE, which
    // is how a theme nobody applied reached storage. Reconcile once: the second pass finds `active`
    // by name and stops.
    if (active.name !== themeName) setThemeName(active.name);
    document.documentElement.setAttribute("data-theme", active.name);
    document.documentElement.setAttribute("data-mode", mode);
    document.documentElement.setAttribute("data-density", density);
    document.documentElement.classList.toggle("dark", mode === "dark");
    loadThemeFonts(active);
    injectDensityCss();
  }, [themeName, mode, density, themes]);

  // Persist on change.
  //
  // The first run is SKIPPED via `skipFirstPersistRef`: state at mount
  // is the SSR-safe default. If we wrote it to storage immediately,
  // we'd clobber the user's stored preference between mount and the
  // post-mount hydration effect that promotes the stored value. After
  // the first call, every subsequent run persists — whether the change
  // came from the hydration effect (no-op write back of the stored
  // value) or a user-driven `setTheme` / `toggleMode` / `setDensity`.
  useEffect(() => {
    if (skipFirstPersistRef.current) {
      skipFirstPersistRef.current = false;
      return;
    }
    // Nothing the user decided yet — see `userDecidedRef`. A hydration echo would rewrite a value
    // that is already there, and an OS-derived mode is not a preference to remember.
    if (!userDecidedRef.current) return;
    if (typeof window === "undefined" || !storageKey) return;
    try {
      window.localStorage.setItem(`${storageKey}:name`, themeName);
      window.localStorage.setItem(`${storageKey}:mode`, mode);
      window.localStorage.setItem(`${storageKey}:density`, density);
    } catch (err) {
      // Storage may fail in private mode; behavior remains correct (state
      // lives in memory). Per HIGH-006 we surface a one-time dev warning so
      // the engineer sees something instead of complete silence.
      warnStorageFailure("persist theme + mode + density", err);
    }
  }, [themeName, mode, density, storageKey]);

  const setTheme = useCallback((name: string) => {
    userDecidedRef.current = true;
    setThemeName(name);
  }, []);
  const setMode = useCallback((next: ThemeMode) => {
    // T5.1 / D6: fix the user preference; subsequent system changes no longer override.
    userOverrodeModeRef.current = true;
    userDecidedRef.current = true;
    setModeState(next);
  }, []);
  const toggleMode = useCallback(() => {
    userOverrodeModeRef.current = true;
    userDecidedRef.current = true;
    setModeState((cur) => (cur === "light" ? "dark" : "light"));
  }, []);
  const setDensity = useCallback((next: Density) => {
    userDecidedRef.current = true;
    setDensityState(next);
  }, []);
  const registerTheme = useCallback((theme: Theme) => {
    setThemes((cur) => {
      const idx = cur.findIndex((t) => t.name === theme.name);
      if (idx >= 0) {
        const next = cur.slice();
        next[idx] = theme;
        return next;
      }
      return [...cur, theme];
    });
  }, []);

  // themes[0] is guaranteed non-undefined by the constructor-time check
  // above (themesProp is non-empty); the non-null assert encodes that
  // invariant for TypeScript, which can't trace it through useState.
  // biome-ignore lint/style/noNonNullAssertion: T2.5 runtime invariant — themesProp non-empty validated at top of function
  const active = themes.find((t) => t.name === themeName) ?? themes[0]!;

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme: active,
      mode,
      themes,
      setTheme,
      setMode,
      toggleMode,
      registerTheme,
    }),
    [active, mode, themes, setTheme, setMode, toggleMode, registerTheme],
  );

  const densityValue = useMemo(() => ({ density, setDensity }), [density, setDensity]);

  return (
    <ThemeContext.Provider value={value}>
      <DensityContext.Provider value={densityValue}>{children}</DensityContext.Provider>
    </ThemeContext.Provider>
  );
}

/**
 * useTheme — access theme state from any component inside <ThemeProvider>.
 * Throws if used outside the provider — fail-fast.
 */
function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error("useTheme must be used inside <ThemeProvider>.");
  }
  return ctx;
}

/**
 * `shapeToCss` is exported for its own tests, not as public API — it is deliberately absent from
 * the package barrel.
 *
 * Testing it through a mounted provider does not work: when validation throws mid-render, React is
 * left working, and testing-library's automatic `cleanup` then throws "Should not already be
 * working" over it. The real failure is replaced by a misleading one that names the wrong test.
 *
 * The behaviour under test is "given a theme, what CSS comes out" — a pure function of its input,
 * with no DOM in it. Calling it directly tests the thing itself instead of a render that happens
 * to reach it.
 */
/**
 * Whether a font stack will pass the injection allowlist.
 *
 * Exported so a UI collecting one can check BEFORE applying rather than after: the provider throws
 * in development, which is right for a theme written in a file and wrong for a text field somebody
 * is still typing into. A single `(` would otherwise take the page down mid-word.
 */
export function isValidFontFamily(value: string): boolean {
  return FONT_FAMILY_PATTERN.test(value);
}

export { ThemeProvider, shapeToCss, useTheme };

import * as DropdownMenu from "@radix-ui/react-dropdown-menu";
import { Check, Moon, Palette, Sun } from "lucide-react";
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";
import { useTheme } from "@/themes/theme-provider";

interface ThemeSwitcherProps {
  className?: string;
  /** If true, renders mode toggle inline next to the theme menu. */
  showModeToggle?: boolean;
}

/**
 * ThemeSwitcher — drop-in theme + mode picker.
 *
 * Two affordances:
 *   - Palette dropdown lists all registered themes with the active marked.
 *   - Optional sun/moon button toggles light/dark.
 *
 * Stateless wrt itself — pulls state from `useTheme()`.
 */
function ThemeSwitcher({ className, showModeToggle = true }: ThemeSwitcherProps): JSX.Element {
  const { theme, themes, setTheme, mode, toggleMode } = useTheme();

  // `false` on the server AND on the client's first render — which is what makes the two agree.
  // Flipping it in an effect is the documented way to render something only the client can know
  // without the first client render disagreeing with the server's.
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
  }, []);

  return (
    <div className={cn("inline-flex items-center gap-1", className)}>
      {/* LOW-006: announce theme + mode changes to assistive tech. The
       * Provider applies tokens via `data-theme`/`data-mode` (visual cue),
       * but screen-reader users get no feedback without this aria-live
       * region. Polite so it doesn't interrupt the user's flow.
       *
       * #155 — the announcement is rendered only AFTER mount, and that is not a workaround for a
       * hydration warning: it is the only honest thing a server can emit here. `mode` is resolved
       * by `ThemeProvider` from `localStorage` and `prefers-color-scheme` in a `useEffect`
       * (`theme-provider.tsx:500`), so the server does not have it — it renders `defaultMode` and
       * the client may render something else. Text content that differs is React #418, which
       * DISCARDS the server markup and rebuilds the tree on the client. Every SSR page mounting
       * this paid that.
       *
       * Nothing is lost by the delay: a live region is announced when its content CHANGES, so an
       * empty one on the server and a filled one after mount is exactly the sequence it exists for.
       * Announcing at mount would also be wrong — a screen reader would read the theme aloud on
       * every page load, which `aria-live="polite"` is meant to avoid. */}
      <span aria-live="polite" aria-atomic="true" className="sr-only">
        {mounted ? `Theme: ${theme.label}, mode: ${mode}` : ""}
      </span>
      <DropdownMenu.Root>
        <DropdownMenu.Trigger asChild>
          <button
            type="button"
            aria-label={`Theme: ${theme.label}`}
            className={cn(
              "inline-flex h-9 items-center gap-2 rounded-lg border border-border/60 bg-card px-3",
              "font-medium font-sans text-body-sm text-foreground",
              "transition-colors hover:bg-muted",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            )}
          >
            <Palette className="size-4 text-primary" aria-hidden="true" />
            <span>{theme.label}</span>
          </button>
        </DropdownMenu.Trigger>
        <DropdownMenu.Portal>
          <DropdownMenu.Content
            align="end"
            sideOffset={6}
            className={cn(
              "z-50 min-w-[16rem] overflow-hidden rounded-lg border bg-popover p-1 text-popover-foreground shadow-md",
              "data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=open]:animate-in",
              "data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=closed]:animate-out",
            )}
          >
            {themes.map((t) => (
              <DropdownMenu.Item
                key={t.name}
                onSelect={() => setTheme(t.name)}
                className={cn(
                  "flex cursor-pointer items-start justify-between gap-3 rounded-md px-2 py-2",
                  "focus:bg-muted focus:outline-none data-[highlighted]:bg-muted",
                )}
              >
                <span className="flex min-w-0 flex-col">
                  <span className="font-medium text-body-sm">{t.label}</span>
                  {t.description ? (
                    <span className="text-body-sm text-muted-foreground">{t.description}</span>
                  ) : null}
                </span>
                {t.name === theme.name ? (
                  <Check className="mt-1 size-4 shrink-0 text-primary" aria-hidden="true" />
                ) : null}
              </DropdownMenu.Item>
            ))}
          </DropdownMenu.Content>
        </DropdownMenu.Portal>
      </DropdownMenu.Root>

      {showModeToggle ? (
        <button
          type="button"
          onClick={toggleMode}
          /*
           * #155, second half. `mode` is read in three places here and only the live region above was
           * guarded; this label and the icon below were not, and both diverge for the same reason —
           * the server has no `mode`, so it renders `defaultMode` while the client may render
           * something else.
           *
           * Measured against the published 1.12.0 in a real browser (theokit's
           * `scripts/probe-hydration.mjs`, Chrome over CDP, built scaffold): React #418 with
           * `args[]=HTML`, and the printed tree named this `aria-label` and the `<Moon>`/`<Sun>`
           * swap. The icon is the worse half: those are different components with different SVG
           * children, so the mismatch is structural and React discards the server markup and rebuilds
           * the whole tree — the value of SSR thrown away on every page load.
           *
           * Guarded the same way the live region already is, deliberately rather than inventing a
           * second pattern: `mounted` is false on the server AND on the client's first render, so the
           * two agree by construction and it does not matter WHAT makes `mode` differ afterwards.
           * A CSS approach (render both icons, let `data-mode` on `<html>` pick) would avoid the
           * one-frame delay, and it needs `<ThemeScript>` to be rendered to beat the first paint —
           * which the default scaffold does not do. That is a larger decision than this fix.
           *
           * The button keeps its box and stays operable while unmounted: `size-9` is on the button and
           * the placeholder is `size-4`, so nothing shifts when the icon arrives.
           */
          aria-label={
            mounted ? `Switch to ${mode === "light" ? "dark" : "light"} mode` : "Switch colour mode"
          }
          className={cn(
            "inline-flex size-9 items-center justify-center rounded-lg border border-border/60 bg-card",
            "text-foreground transition-colors hover:bg-muted",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          )}
        >
          {mounted ? (
            mode === "light" ? (
              <Moon className="size-4" />
            ) : (
              <Sun className="size-4" />
            )
          ) : (
            <span className="size-4" aria-hidden="true" />
          )}
        </button>
      ) : null}
    </div>
  );
}

export { ThemeSwitcher };

/**
 * Color helpers for `ColorScale` and `defineTheme`.
 *
 * Post-T2.6 (community-best-practices alignment, ADR-0005): the canonical
 * output format is OKLCH (`"oklch(L C H)"`). Built-in themes also use OKLCH
 * after the T2.4 migration. The CSS regex (`COLOR_VALUE_PATTERN`) accepts
 * both formats for backward compatibility — legacy themes pinned to the
 * HSL split format keep working.
 *
 * Helpers:
 *   - hex(input)      → "oklch(L C H)"  (NEW — primary path post-T2.6)
 *   - rgb(r, g, b)    → "oklch(L C H)"  (NEW)
 *   - hexToHsl(input) → "H S% L%"       (legacy — deprecated, kept 1 minor)
 *   - rgbToHsl(...)   → "H S% L%"       (legacy — deprecated)
 *
 * Alpha channels are intentionally discarded — `ColorScale` is opaque;
 * compose alpha in CSS via `color-mix(in oklch, var(--primary) 50%, transparent)`.
 *
 * RFC: `wiki/rfcs/0005-theming-and-sizes.md`.
 */

function hexCharToNibble(ch: string): number {
  if (ch >= "0" && ch <= "9") return ch.charCodeAt(0) - 48;
  if (ch >= "a" && ch <= "f") return ch.charCodeAt(0) - 87;
  if (ch >= "A" && ch <= "F") return ch.charCodeAt(0) - 55;
  throw new Error(`hex(): invalid hex character "${ch}"`);
}

function parseHex(input: string): { r: number; g: number; b: number } {
  if (!input.startsWith("#")) {
    throw new Error(`hex(): expected '#'-prefixed input, got "${input}"`);
  }
  const body = input.slice(1);
  let r: number;
  let g: number;
  let b: number;
  if (body.length === 3 || body.length === 4) {
    // Short form #rgb or #rgba — expand each nibble. charAt always returns
    // a string (empty for OOB), so hexCharToNibble throws on the empty
    // string the same way it does on any invalid char — no NonNull needed.
    const nr = hexCharToNibble(body.charAt(0));
    const ng = hexCharToNibble(body.charAt(1));
    const nb = hexCharToNibble(body.charAt(2));
    r = (nr << 4) | nr;
    g = (ng << 4) | ng;
    b = (nb << 4) | nb;
    // Alpha char (body[3]) is silently dropped per spec — ColorScale is opaque.
  } else if (body.length === 6 || body.length === 8) {
    r = (hexCharToNibble(body.charAt(0)) << 4) | hexCharToNibble(body.charAt(1));
    g = (hexCharToNibble(body.charAt(2)) << 4) | hexCharToNibble(body.charAt(3));
    b = (hexCharToNibble(body.charAt(4)) << 4) | hexCharToNibble(body.charAt(5));
    // Bytes 6-7 (alpha) silently dropped.
  } else {
    throw new Error(
      `hex(): invalid length ${body.length} for hex input "${input}" — expected 3, 4, 6, or 8 hex chars after the '#'.`,
    );
  }
  return { r, g, b };
}

/**
 * Convert sRGB ([0, 255]^3) to OKLCH via D65 linearization and Oklab matrices.
 * Inline implementation (no external dep): the Oklab paper (Björn Ottosson,
 * 2020) defines the conversion as two matrix products + cube-root nonlinearity.
 * Output: rounded to 3 decimals for L/C, 1 decimal for H.
 */
function rgbToOklch(r: number, g: number, b: number): string {
  // sRGB → linear RGB (gamma decoding).
  const linearize = (c: number): number => {
    const cn = c / 255;
    return cn <= 0.04045 ? cn / 12.92 : ((cn + 0.055) / 1.055) ** 2.4;
  };
  const rl = linearize(r);
  const gl = linearize(g);
  const bl = linearize(b);

  // Linear RGB → LMS via Oklab matrix.
  const l_ = 0.4122214708 * rl + 0.5363325363 * gl + 0.0514459929 * bl;
  const m_ = 0.2119034982 * rl + 0.6806995451 * gl + 0.1073969566 * bl;
  const s_ = 0.0883024619 * rl + 0.2817188376 * gl + 0.6299787005 * bl;

  const l = Math.cbrt(l_);
  const m = Math.cbrt(m_);
  const s = Math.cbrt(s_);

  // LMS' → Oklab.
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bComp = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;

  // Oklab → OKLCH.
  const C = Math.sqrt(a * a + bComp * bComp);
  let H = (Math.atan2(bComp, a) * 180) / Math.PI;
  if (H < 0) H += 360;

  const round = (n: number, d: number): number => {
    const f = 10 ** d;
    return Math.round(n * f) / f;
  };
  // Neutrals (C ≈ 0) have an undefined hue; emit 0 to keep regex-friendly.
  const hOut = C < 1e-4 ? 0 : round(H, 1);
  return `oklch(${round(L, 3)} ${round(C, 3)} ${hOut})`;
}

function rgbToHsl(r: number, g: number, b: number): string {
  const rn = r / 255;
  const gn = g / 255;
  const bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const l = (max + min) / 2;
  let h = 0;
  let s = 0;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case rn:
        h = (gn - bn) / d + (gn < bn ? 6 : 0);
        break;
      case gn:
        h = (bn - rn) / d + 2;
        break;
      default:
        h = (rn - gn) / d + 4;
        break;
    }
    h *= 60;
  }
  const hh = Math.round(h);
  const ss = Math.round(s * 100);
  const ll = Math.round(l * 100);
  return `${hh} ${ss}% ${ll}%`;
}

/**
 * Convert a hex color string to the HSL string-tuple format used by
 * `ColorScale` ("`H S% L%`", e.g. `"262 83% 58%"`).
 *
 * Accepts `#rgb`, `#rgba`, `#rrggbb`, `#rrggbbaa`. Case-insensitive.
 * Alpha bytes are silently dropped — use `hsl(var(--primary) / 0.5)`
 * in CSS for transparency.
 *
 * @throws if the input is malformed.
 *
 * @example
 *   hex("#A855F7")   // "oklch(0.628 0.225 296)"
 *   hex("#a855f7")   // same — case-insensitive
 *   hex("#abc")      // expanded to "#aabbcc"
 */
export function hex(input: string): string {
  const { r, g, b } = parseHex(input);
  return rgbToOklch(r, g, b);
}

/**
 * Legacy helper that returns HSL string-tuple format (pre-T2.6).
 *
 * @deprecated Since 2026-06-03 — use `hex(input)` which returns OKLCH.
 *   Kept for one minor cycle to avoid breaking consumers that authored
 *   themes using the HSL split format. Both formats are accepted by
 *   `ColorScale` and by `<ThemeProvider>` runtime validation.
 */
export function hexToHsl(input: string): string {
  const { r, g, b } = parseHex(input);
  return rgbToHsl(r, g, b);
}

/**
 * Convert an RGB triplet (each in `[0, 255]`) to the HSL string-tuple
 * format used by `ColorScale`.
 *
 * @throws if any channel is out of `[0, 255]`.
 *
 * @example
 *   rgb(168, 85, 247)  // "oklch(0.628 0.225 296)"
 */
export function rgb(r: number, g: number, b: number): string {
  for (const value of [r, g, b]) {
    if (!Number.isFinite(value) || value < 0 || value > 255) {
      throw new Error(
        `rgb(): channel out of range — expected 0..255, got ${value}. Did you mix percentage values?`,
      );
    }
  }
  return rgbToOklch(Math.round(r), Math.round(g), Math.round(b));
}

/**
 * Legacy helper that returns HSL string-tuple format (pre-T2.6).
 *
 * @deprecated Since 2026-06-03 — use `rgb(r, g, b)` which returns OKLCH.
 */
export function rgbToHslLegacy(r: number, g: number, b: number): string {
  for (const value of [r, g, b]) {
    if (!Number.isFinite(value) || value < 0 || value > 255) {
      throw new Error(`rgbToHslLegacy(): channel out of range — expected 0..255, got ${value}.`);
    }
  }
  return rgbToHsl(Math.round(r), Math.round(g), Math.round(b));
}

/**
 * `defineTheme(input)` — build a `Theme` from a partial override.
 *
 * Reduces the boilerplate of authoring a custom theme from 58 colour
 * keys (`light` × 29 + `dark` × 29) to "just what you want to change".
 * The merge always uses `violetForge` as the base — this is a pure,
 * deterministic helper that does not depend on whatever theme is active
 * at the call site.
 *
 * The `Theme` object it returns is drop-in compatible with
 * `<ThemeProvider themes={[...]}>` — same shape as `violetForge`,
 * `classicPaper`, and `auroraTerminal`.
 *
 * Honest caveat: if you override `light.primary` but NOT `dark.primary`,
 * the two modes will use different colours — your override in light,
 * Violet Forge's default in dark. That's intentional. Pass both sides
 * to keep them in sync.
 *
 * Omitting a mode *entirely* is the same rule with a much larger blast
 * radius, so it warns in development: a theme that defines only `dark`
 * renders as Violet Forge for every visitor whose system is set to light,
 * which `ThemeProvider` follows by default via `respectSystemMode`. Pass
 * an empty object (`light: {}`) to say the inheritance is deliberate and
 * silence the warning.
 *
 * @example
 *   import { defineTheme, hex } from "@theokit/ui";
 *   export const corp = defineTheme({
 *     name: "corp",
 *     light: { primary: hex("#0EA5E9") },
 *     dark: { primary: hex("#38BDF8") },
 *   });
 *
 * RFC: `wiki/rfcs/0005-theming-and-sizes.md`.
 */
import { isDev } from "@/lib/env";
import type {
  ColorScale,
  MotionScale,
  RadiusScale,
  ShadowScale,
  SpaceScale,
  Theme,
  ThemeFonts,
} from "@/themes/types";
import { violetForge } from "@/themes/violet-forge";

const NAME_PATTERN = /^[a-z][a-z0-9-]*$/i;

export interface DefineThemeInput {
  /**
   * Stable id used in `data-theme="<name>"` on the root element. Must
   * match `/^[a-z][a-z0-9-]*$/i` (CSS-identifier-safe). Required.
   */
  name: string;
  /**
   * Human-readable label for theme switchers. Defaults to the
   * capitalized version of `name` (e.g. "corp" → "Corp").
   */
  label?: string;
  /** Optional one-line description shown in switchers. */
  description?: string;
  /**
   * Override light-mode colours. Any key omitted is inherited from
   * `violetForge.light`. See `ColorScale` for the full list.
   *
   * Leaving this out while `dark` is set warns in development — pass `{}`
   * to declare the inheritance deliberate.
   */
  light?: Partial<ColorScale>;
  /**
   * Override dark-mode colours. Any key omitted is inherited from
   * `violetForge.dark`.
   *
   * Leaving this out while `light` is set warns in development — pass `{}`
   * to declare the inheritance deliberate.
   */
  dark?: Partial<ColorScale>;
  /**
   * Override fonts (`display`, `body`, `mono`). Any key omitted is
   * inherited from `violetForge.fonts`.
   */
  fonts?: Partial<ThemeFonts>;
  /**
   * Remote stylesheets to load for this theme's fonts, injected as
   * `<link rel="stylesheet">`.
   *
   * Omit it, which is what every built-in theme except `classicPaper` now does: Geist and Geist
   * Mono are self-hosted by `@theokit/ui/styles.css`, so no request is needed and none is made.
   * This used to default to `violetForge.fontUrls` and fetch from a CDN — redundant, and blocked
   * by theokit's default `style-src 'self' 'unsafe-inline'` (#125).
   *
   * Supplying one is a deliberate choice with a consequence: the consumer must widen their CSP to
   * admit the stylesheet host in `style-src` and the font host in `font-src`.
   */
  fontUrls?: string[];
  /**
   * Corner radii. Unlike the colour scales, these do NOT inherit from Violet Forge: an omitted
   * key emits nothing and the scale in `tokens.css` stands.
   *
   * The difference is deliberate. Colour has to be complete — a palette missing `background` is
   * not a palette — so the merge fills the gaps. Shape is a set of independent adjustments, and
   * inheriting them from another theme would mean a theme that only wants square corners silently
   * adopts Violet Forge's spacing and elevation too.
   */
  radius?: RadiusScale;
  /** The spacing base every `p-*`/`gap-*`/`m-*` utility multiplies. Omitted leaves it alone. */
  spacing?: string;
  /** Elevation. Omitted keys keep the palette-derived shadows. */
  shadows?: ShadowScale;
  /** The named spacing steps a consumer reads directly. Omitted keys keep the defaults. */
  space?: SpaceScale;
  /** Durations and easings. Omitted keys keep the defaults. */
  motion?: MotionScale;
}

function defaultLabel(name: string): string {
  if (name.length === 0) return name;
  return name.charAt(0).toUpperCase() + name.slice(1);
}

/**
 * Warn when a theme paints one mode and leaves the other entirely absent.
 *
 * The merge below is documented and deliberate, but the failure it produces is silent and total:
 * every key of the missing mode comes from Violet Forge, so a theme that defines only `dark` is a
 * different product in light — different background, different accent, different brand. Nothing
 * in `tsc`, lint, tests or build sees it, because it is a valid `Theme`; it surfaces only when
 * somebody opens the app on a system set to the other mode.
 *
 * `undefined` (forgot) is distinguished from `{}` (meant it), so the escape hatch costs two
 * characters and reads as intent at the call site.
 */
function warnOneSidedTheme(name: string, input: DefineThemeInput): void {
  if (!isDev()) return;

  const given = input.light !== undefined ? "light" : "dark";
  const missing = given === "light" ? "dark" : "light";
  const overrides = Object.keys(
    given === "light" ? (input.light ?? {}) : (input.dark ?? {}),
  ).length;
  if (overrides === 0) return;

  // biome-ignore lint/suspicious/noConsole: dev-only authoring diagnostic (#81)
  console.warn(
    `[@theokit/ui] defineTheme("${name}") sets ${String(overrides)} ${given}-mode colour${
      overrides === 1 ? "" : "s"
    } but omits \`${missing}\` entirely, so every ${missing}-mode key falls back to Violet Forge — a different palette, not a dimmer or brighter version of yours. ThemeProvider follows the system preference by default (respectSystemMode), so visitors in ${missing} mode see Violet Forge. Define \`${missing}\`, or pass \`${missing}: {}\` if inheriting it is deliberate.`,
  );
}

export function defineTheme(input: DefineThemeInput): Theme {
  if (typeof input?.name !== "string" || input.name.length === 0) {
    throw new Error("defineTheme: `name` is required and cannot be empty.");
  }
  if (!NAME_PATTERN.test(input.name)) {
    throw new Error(
      `defineTheme: invalid name "${input.name}". Must match /^[a-z][a-z0-9-]*$/i — letters, digits, and hyphens only, starting with a letter.`,
    );
  }

  const oneSided = (input.light === undefined) !== (input.dark === undefined);
  if (oneSided) warnOneSidedTheme(input.name, input);

  const lightOverride = input.light ?? {};
  const darkOverride = input.dark ?? {};
  const fontsOverride = input.fonts ?? {};

  const theme: Theme = {
    name: input.name,
    label: input.label ?? defaultLabel(input.name),
    description: input.description,
    fonts: { ...violetForge.fonts, ...fontsOverride },
    light: { ...violetForge.light, ...lightOverride },
    dark: { ...violetForge.dark, ...darkOverride },
    // No `?? violetForge.fontUrls` any more: Violet Forge no longer carries any, so the
    // fallback resolved to `undefined` while reading as though a default existed (#125).
    fontUrls: input.fontUrls,
  };

  // Carried through only when present, so `theme.radius` stays `undefined` rather than becoming an
  // empty object. `shapeToCss` reads that difference: nothing declared means no rule emitted, and
  // an empty rule in the injected sheet is noise for whoever reads the page's styles.
  if (input.radius !== undefined) theme.radius = input.radius;
  if (input.spacing !== undefined) theme.spacing = input.spacing;
  if (input.shadows !== undefined) theme.shadows = input.shadows;
  if (input.space !== undefined) theme.space = input.space;
  if (input.motion !== undefined) theme.motion = input.motion;

  return theme;
}

/**
 * Derive a whole palette from one colour.
 *
 * This is the half of a theme editor that separates a colour picker from a design system. Asking
 * somebody to choose twenty-nine colours is asking them to be a designer; asking for one and
 * deriving the rest is what Radix and Material 3 do, and it only works in a perceptual space —
 * lightening in HSL changes how saturated a colour *looks*, so a scale built that way drifts in
 * ways the numbers do not show.
 *
 * OKLCH makes lightness mean what the eye means by it, which is why every step here moves `L` and
 * leaves hue alone.
 *
 * WHAT MAKES THIS MORE THAN A GRADIENT: the pairs that carry text are solved for contrast rather
 * than assigned and hoped over. `primary-foreground` is whichever of near-black and near-white
 * clears the threshold against `primary` — and when neither does, `primary` itself is walked in
 * lightness until one of them does. A derived palette that fails WCAG is exactly the artefact the
 * audit exists to reject, so deriving one would be a strange thing for this package to do.
 */

import { WCAG_AA, contrastRatio } from "@/themes/contrast";
import type { ColorScale, ThemeMode } from "@/themes/types";

/** OKLCH components, in the units CSS uses: L 0–1, C 0–0.4ish, H degrees. */
interface Oklch {
  l: number;
  c: number;
  h: number;
}

const clamp = (n: number, min: number, max: number): number => Math.min(max, Math.max(min, n));

/** Rounded to what CSS needs, so a theme file does not carry sixteen decimal places. */
function css({ l, c, h }: Oklch): string {
  const r = (n: number, places: number): string => Number(n.toFixed(places)).toString();
  return `oklch(${r(clamp(l, 0, 1), 4)} ${r(Math.max(0, c), 4)} ${r(((h % 360) + 360) % 360, 2)})`;
}

/** Reads `oklch()`, `#rrggbb` and `rgb()` into OKLCH. Returns `null` for anything else. */
export function toOklch(color: string): Oklch | null {
  const direct = /^oklch\(\s*([\d.%]+)\s+([\d.]+)\s+([\d.]+)/i.exec(color.trim());
  if (direct?.[1] !== undefined && direct[2] !== undefined && direct[3] !== undefined) {
    const l = direct[1].endsWith("%") ? Number.parseFloat(direct[1]) / 100 : Number(direct[1]);
    return { l, c: Number(direct[2]), h: Number(direct[3]) };
  }

  const rgb = toLinearRgb(color);
  if (!rgb) return null;
  return linearRgbToOklch(rgb);
}

/** `#rrggbb` / `rgb()` → linear sRGB. */
function toLinearRgb(color: string): [number, number, number] | null {
  const linearise = (channel: number): number =>
    channel <= 0.03928 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;

  const hex = /^#([0-9a-f]{6})$/i.exec(color.trim())?.[1];
  if (hex !== undefined) {
    const at = (i: number): number => Number.parseInt(hex.slice(i, i + 2), 16) / 255;
    return [linearise(at(0)), linearise(at(2)), linearise(at(4))];
  }

  const inner = /^rgba?\(([^)]+)\)$/i.exec(color.trim())?.[1];
  if (inner !== undefined) {
    const parts =
      inner
        .split("/")[0]
        ?.trim()
        .split(/[\s,]+/)
        .filter(Boolean) ?? [];
    if (parts.length < 3) return null;
    const at = (i: number): number => Number(parts[i]) / 255;
    return [linearise(at(0)), linearise(at(1)), linearise(at(2))];
  }

  return null;
}

/** Linear sRGB → OKLCH. The inverse of the transform in `contrast.ts`, same constants. */
function linearRgbToOklch([r, g, b]: [number, number, number]): Oklch {
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);

  const lightness = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bb = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;

  return {
    l: lightness,
    c: Math.sqrt(a * a + bb * bb),
    h: ((Math.atan2(bb, a) * 180) / Math.PI + 360) % 360,
  };
}

/**
 * Pick the readable text colour for a surface, and say when neither works.
 *
 * Returning `null` rather than "the better of two bad options" is what lets the caller fix the
 * surface instead of shipping a pair that fails. A function that always answers would make the
 * threshold decorative.
 */
function readableOn(surface: string, minimum: number, hue: number): string | null {
  const candidates = [css({ l: 0.14, c: 0.01, h: hue }), css({ l: 0.99, c: 0.005, h: hue })];
  const scored = candidates
    .map((candidate) => ({ candidate, ratio: contrastRatio(candidate, surface) ?? 0 }))
    .sort((a, b) => b.ratio - a.ratio);

  const best = scored[0];
  return best !== undefined && best.ratio >= minimum ? best.candidate : null;
}

/**
 * Move a surface's lightness until some text colour clears the threshold on it.
 *
 * The direction is away from the mode's own background — a dark theme darkens its accents, a light
 * theme lightens them — so a brand colour lands where it still reads as itself rather than being
 * dragged to the nearest passing grey. Steps are 0.02 in OKLCH lightness, roughly the smallest
 * change a person notices, so the result is never further from the requested colour than the
 * constraint requires.
 *
 * WHETHER THIS LOOP EVER RUNS DEPENDS ENTIRELY ON THE THRESHOLD, and it is worth writing down
 * because the first version of this file walked for a threshold that never needed it. Near-black
 * and near-white bracket the lightness range, so:
 *
 *   3:1   — no dead band. One of the two always clears it, at every luminance.
 *   4.5:1 — dead band at luminance 0.173–0.251. Neither works; the surface has to move.
 *   7:1   — dead band 0.093–0.418, most of the useful range.
 *
 * So a derivation targeting only 3:1 would make this function a no-op. It targets 4.5 for the
 * surfaces that carry button labels — see `deriveColorScale` — which is both why the loop exists
 * and why a derived palette clears the audit with room rather than by exactly one hundredth.
 */
function solveSurface(
  seed: Oklch,
  minimum: number,
  mode: ThemeMode,
): { surface: string; text: string } {
  const direction = mode === "dark" ? -1 : 1;

  for (let step = 0; step <= 40; step += 1) {
    for (const sign of step === 0 ? [1] : [direction, -direction]) {
      const l = clamp(seed.l + sign * step * 0.02, 0.05, 0.98);
      const surface = css({ ...seed, l });
      const text = readableOn(surface, minimum, seed.h);
      if (text !== null) return { surface, text };
    }
  }

  // Unreachable for any real hue: near-black and near-white bracket the whole lightness range, so
  // one of them clears 3:1 somewhere. Kept as an explicit floor rather than a non-null assertion.
  const surface = css({ ...seed, l: mode === "dark" ? 0.35 : 0.75 });
  return { surface, text: css({ l: mode === "dark" ? 0.99 : 0.14, c: 0.005, h: seed.h }) };
}

export interface DeriveOptions {
  /** The one colour a person chooses. Hex, rgb() or oklch(). */
  seed: string;
  mode: ThemeMode;
  /**
   * How much of the seed's hue bleeds into the greys, 0–0.03.
   *
   * `0` gives true neutrals. The default tints them very slightly toward the brand, which is what
   * stops a palette reading as "a colour on top of Bootstrap" — the greys belong to it too.
   */
  neutralChroma?: number;
}

/** Fixed hues for the semantic colours, which mean what they mean regardless of the brand. */
const SEMANTIC_HUES = { destructive: 27, success: 145, warning: 85, info: 250 } as const;

/**
 * Build a complete `ColorScale` from one colour.
 *
 * Every pair the contrast audit checks is solved rather than assigned, so the result passes
 * `auditColorScale` by construction — which the tests assert across a sweep of hues rather than on
 * one convenient example.
 *
 * Returns `null` only when the seed cannot be read at all; an out-of-gamut or extreme seed is
 * handled by moving it, not by refusing.
 */
export function deriveColorScale(options: DeriveOptions): ColorScale | null {
  const seed = toOklch(options.seed);
  if (!seed) return null;

  const { mode } = options;
  const dark = mode === "dark";
  const tint = clamp(options.neutralChroma ?? 0.006, 0, 0.03);
  const h = seed.h;

  const neutral = (l: number, c = tint): string => css({ l, c, h });

  const background = neutral(dark ? 0.16 : 0.99);
  const card = neutral(dark ? 0.2 : 1, dark ? tint : 0);
  const popover = card;
  const muted = neutral(dark ? 0.26 : 0.96);
  const border = neutral(dark ? 0.29 : 0.9);

  // Text is solved against the surface it sits on, not assumed from the mode.
  const foreground = readableOn(background, WCAG_AA.normalText, h) ?? neutral(dark ? 0.95 : 0.15);
  const cardForeground = readableOn(card, WCAG_AA.normalText, h) ?? foreground;
  const mutedForeground = solveSurface({ l: dark ? 0.72 : 0.48, c: tint * 2, h }, 0, mode).surface;

  /*
   * Solved at 4.5, not at the 3 the audit demands.
   *
   * These are the surfaces that carry button labels, and a label is normal-sized text — the audit
   * holds them to the large-text threshold by a convention this package inherited, which is right
   * for judging a hand-written theme and too loose for generating one. A derived palette should
   * clear the bar with room, not land on it.
   *
   * It is also what makes `solveSurface` do work: at 3:1 there is no lightness where neither
   * near-black nor near-white reads, so the walk would never take a step.
   */
  const primary = solveSurface(seed, WCAG_AA.normalText, mode);
  const secondary = solveSurface({ l: dark ? 0.28 : 0.94, c: tint, h }, WCAG_AA.normalText, mode);

  // `accent` is tonal — used behind badges and hover states at `/10` and `/15`, rarely under
  // normal text — so the audit's own threshold is the right one here.
  const accent = solveSurface({ ...seed, c: seed.c * 0.9 }, WCAG_AA.largeText, mode);

  const semantic = (hue: number): { surface: string; text: string } =>
    solveSurface({ l: dark ? 0.65 : 0.55, c: 0.15, h: hue }, WCAG_AA.normalText, mode);

  const destructive = semantic(SEMANTIC_HUES.destructive);
  const success = semantic(SEMANTIC_HUES.success);
  const warning = semantic(SEMANTIC_HUES.warning);
  const info = semantic(SEMANTIC_HUES.info);

  return {
    background,
    foreground,
    card,
    "card-foreground": cardForeground,
    popover,
    "popover-foreground": cardForeground,
    primary: primary.surface,
    "primary-foreground": primary.text,
    secondary: secondary.surface,
    "secondary-foreground": secondary.text,
    accent: accent.surface,
    "accent-foreground": accent.text,
    muted,
    // `muted-foreground` is auxiliary text and is held to the large-text threshold, matching the
    // audit — solved against `muted`, which is the surface it actually sits on.
    "muted-foreground": readableOn(muted, WCAG_AA.largeText, h) ?? mutedForeground,
    border,
    input: border,
    ring: primary.surface,
    destructive: destructive.surface,
    "destructive-foreground": destructive.text,
    success: success.surface,
    "success-foreground": success.text,
    warning: warning.surface,
    "warning-foreground": warning.text,
    info: info.surface,
    "info-foreground": info.text,
    // Operational status mirrors the semantic group, which is what the built-in themes do. A
    // consumer wanting visually distinct status surfaces overrides these.
    "status-online": success.surface,
    "status-online-foreground": success.text,
    "status-offline": destructive.surface,
    "status-offline-foreground": destructive.text,
    "status-degraded": warning.surface,
    "status-degraded-foreground": warning.text,
    "status-info": info.surface,
    "status-info-foreground": info.text,
  };
}

