export interface ThemeEditorProps {
  className?: string;
  /**
   * Where the edited theme goes when the person is done.
   *
   * Called with a complete `Theme`. Not called when the audit fails, unless `allowFailing` is set:
   * the component's job is to not hand back something unreadable, and a callback that fires anyway
   * would make the audit decorative.
   */
  onCommit?: (theme: Theme) => void;
  /**
   * Let a failing theme be committed anyway.
   *
   * Exists because a contrast ratio is a floor, not a law: a decorative surface, a disabled state,
   * a brand colour signed off with an exception. The default is `false` so the exception is
   * something a consumer opts into, in code, rather than something a person clicks past.
   */
  allowFailing?: boolean;
  /** Name for the theme being built. Defaults to `custom`. */
  name?: string;
  /**
   * Override any of the strings the editor renders.
   *
   * Partial: pass the words you care about, inherit the rest. Nested groups merge one level, so
   * translating two colour names does not mean restating eleven.
   */
  labels?: DeepPartialLabels;
}

/** `labels` accepts a subset, including a subset of each nested group. */
type DeepPartialLabels = Partial<
  Omit<
    ThemeEditorLabels,
    | "colours"
    | "corners"
    | "density"
    | "groups"
    | "elevation"
    | "motion"
    | "typography"
    | "fontSlots"
  >
> & {
  colours?: Partial<ThemeEditorLabels["colours"]>;
  corners?: Partial<ThemeEditorLabels["corners"]>;
  density?: Partial<ThemeEditorLabels["density"]>;
  groups?: Partial<ThemeEditorLabels["groups"]>;
  elevation?: Partial<ThemeEditorLabels["elevation"]>;
  motion?: Partial<ThemeEditorLabels["motion"]>;
  typography?: Partial<ThemeEditorLabels["typography"]>;
  fontSlots?: Partial<ThemeEditorLabels["fontSlots"]>;
};

/** One level of merge for the nested groups; a plain spread would drop the untranslated keys. */
function mergeLabels(overrides: DeepPartialLabels | undefined): ThemeEditorLabels {
  if (!overrides) return DEFAULT_LABELS;
  return {
    ...DEFAULT_LABELS,
    ...overrides,
    colours: { ...DEFAULT_LABELS.colours, ...overrides.colours },
    corners: { ...DEFAULT_LABELS.corners, ...overrides.corners },
    density: { ...DEFAULT_LABELS.density, ...overrides.density },
    groups: { ...DEFAULT_LABELS.groups, ...overrides.groups },
    elevation: { ...DEFAULT_LABELS.elevation, ...overrides.elevation },
    motion: { ...DEFAULT_LABELS.motion, ...overrides.motion },
    typography: { ...DEFAULT_LABELS.typography, ...overrides.typography },
    fontSlots: { ...DEFAULT_LABELS.fontSlots, ...overrides.fontSlots },
  };
}

/**
 * `<input type="color">` accepts hex and nothing else.
 *
 * Every built-in theme is written in OKLCH, so without the conversion the editor opens with every
 * swatch black — the palette is loaded, the control just cannot show it. Black is still the last
 * resort for a value nothing can read, because the input needs *some* string.
 */
function asSwatch(value: string | undefined): string {
  if (value === undefined) return "#000000";
  return cssColorToHex(value) ?? "#000000";
}

function ThemeEditor({
  className,
  onCommit,
  allowFailing = false,
  name = "custom",
  labels: labelOverrides,
}: ThemeEditorProps): JSX.Element {
  const { theme: active, mode, registerTheme, setTheme } = useTheme();
  const { setDensity } = useDensity();
  const labels = useMemo(() => mergeLabels(labelOverrides), [labelOverrides]);

  /**
   * Seeded from the active theme, so the editor opens on what the person is already looking at
   * rather than on a blank palette they have to rebuild from memory.
   *
   * Captured ONCE, and that is not a detail. Applying a change makes the edited theme the active
   * one, so `active` stops being where the person started the moment they touch anything — reading
   * it again in `reset` restored the broken palette instead of the original one, which made the
   * button do nothing visible after the first edit.
   */
  const [origin] = useState<Record<ThemeMode, Partial<ColorScale>>>(() => {
    const seedFor = (m: ThemeMode): Partial<ColorScale> => {
      const scale = active[m];
      const seed: Partial<ColorScale> = {};
      for (const token of EDITABLE_COLORS) seed[token] = scale[token];
      return seed;
    };
    return { light: seedFor("light"), dark: seedFor("dark") };
  });
  const [baseScales] = useState<Record<ThemeMode, ColorScale>>(() => ({
    light: active.light,
    dark: active.dark,
  }));

  /**
   * Both modes are held, and both are emitted.
   *
   * The editor edits whichever mode is active, but a theme is not one palette — it is two, and a
   * person who tunes the dark one and switches to light should not find their work replaced by
   * Violet Forge. Keeping a single scale meant the mode not being edited was emitted as `{}`, which
   * inherits: exactly the silent one-sided theme that `defineTheme` warns about
   * (usetheokit/theokit-ui#81), produced by the tool that is supposed to prevent it.
   */
  const [colorsByMode, setColorsByMode] = useState<Record<ThemeMode, Partial<ColorScale>>>(origin);
  const colors = colorsByMode[mode];
  const [radius, setRadius] = useState<string>(DEFAULT_RADIUS);
  const [spacing, setSpacing] = useState<string>(DEFAULT_SPACING);
  const [elevation, setElevation] = useState<ElevationKey>("inherit");
  const [motion, setMotion] = useState<MotionKey>("inherit");
  const [typography, setTypography] = useState<TypographyKey>("inherit");
  /**
   * A custom stack, for when none of the presets is the brand's typeface.
   *
   * Presets cover the common case and keep the three faces agreeing with each other; this is the
   * escape hatch for the case a preset cannot serve, which for a design system is most of the ones
   * that matter — a company with its own type does not want "Geometric", it wants its own.
   *
   * Empty means unused, so the preset stays in charge until somebody types something.
   */
  const [customFonts, setCustomFonts] = useState<Partial<ThemeFonts>>({});
  const [openGroup, setOpenGroup] = useState<string>(COLOR_GROUPS[0].id);

  // Audited against the palette the editor opened on, not the live one — the live one already
  // contains these edits, so folding it in would compare a change against itself.
  const scale = useMemo(() => ({ ...baseScales[mode], ...colors }), [baseScales, mode, colors]);
  const findings = useMemo(() => auditColorScale(scale), [scale]);
  const failing = findings.filter((f) => !f.passes);
  const readable = failing.length === 0;

  const build = useCallback(
    (
      nextByMode: Record<ThemeMode, Partial<ColorScale>>,
      nextRadius: string,
      nextSpacing: string,
      nextElevation: ElevationKey = elevation,
      nextMotion: MotionKey = motion,
      nextTypography: TypographyKey = typography,
      nextCustom: Partial<ThemeFonts> = customFonts,
    ): Theme =>
      defineTheme({
        name,
        label: "Custom",
        // BOTH modes, always. Emitting `{}` for the one not being edited inherits it from Violet
        // Forge — the silent one-sided theme `defineTheme` warns about, produced by the very tool
        // meant to prevent it. Seeded from the active theme, so an untouched mode carries what it
        // already had rather than nothing.
        light: nextByMode.light,
        dark: nextByMode.dark,
        radius: buildRadius(nextRadius),
        spacing: nextSpacing,
        shadows: ELEVATION_PRESETS[nextElevation],
        motion: MOTION_PRESETS[nextMotion],
        // Preset first, then whatever was typed — per slot, so a custom display face can sit over
        // a preset's body and mono rather than forcing all three to be re-entered.
        fonts: mergeFonts(TYPOGRAPHY_PRESETS[nextTypography], nextCustom),
      }),
    [name, elevation, motion, typography, customFonts],
  );

  /** Applies live: the page repaints from the cascade, with no rebuild and no reload. */
  const apply = useCallback(
    (
      nextByMode: Record<ThemeMode, Partial<ColorScale>>,
      nextRadius: string,
      nextSpacing: string,
      nextElevation?: ElevationKey,
      nextMotion?: MotionKey,
      nextTypography?: TypographyKey,
      nextCustom?: Partial<ThemeFonts>,
    ) => {
      const next = build(
        nextByMode,
        nextRadius,
        nextSpacing,
        nextElevation,
        nextMotion,
        nextTypography,
        nextCustom,
      );
      registerTheme(next);
      setTheme(next.name);
    },
    [build, registerTheme, setTheme],
  );

  /** Writes a palette for the mode being edited, leaving the other one as it was. */
  const commitColors = useCallback(
    (next: Partial<ColorScale>) => {
      const byMode = { ...colorsByMode, [mode]: next };
      setColorsByMode(byMode);
      return byMode;
    },
    [colorsByMode, mode],
  );

  const onColorChange = useCallback(
    (token: keyof ColorScale) => (event: ChangeEvent<HTMLInputElement>) => {
      apply(commitColors({ ...colors, [token]: event.target.value }), radius, spacing);
    },
    [colors, radius, spacing, apply, commitColors],
  );

  const onRadiusChange = useCallback(
    (value: string) => {
      setRadius(value);
      apply(colorsByMode, value, spacing);
    },
    [colorsByMode, spacing, apply],
  );

  /**
   * One colour becomes the whole palette.
   *
   * This is the control that makes the editor usable by someone who is not a designer. Choosing
   * twenty-nine colours is a design job; choosing one and deriving the rest is what Radix and
   * Material 3 do, and it only works because the derivation solves for contrast rather than
   * interpolating — the result clears the audit by construction.
   *
   * Only the tokens this editor shows are taken. The derivation produces the full scale, but
   * writing tokens the person cannot see back into their theme would change things they never
   * chose and cannot undo from here.
   */
  const onSeedChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      const derived = deriveColorScale({ seed: event.target.value, mode });
      if (!derived) return;

      const next: Partial<ColorScale> = { ...colors };
      for (const token of EDITABLE_COLORS) next[token] = derived[token];
      apply(commitColors(next), radius, spacing);
    },
    [colors, radius, spacing, mode, apply, commitColors],
  );

  /**
   * Density is one decision and two mechanisms, so this control moves both.
   *
   * `--spacing` (a theme token) scales `p-*`, `gap-*` and `m-*`; `data-density` (the provider's own
   * attribute) drives `--theo-control-h` / `--theo-control-px`, which is what sets the height of a
   * control. Leaving them on separate controls meant "compact" tightened the layout and left every
   * input at its comfortable height — half a change, and the half nobody would think to look for.
   *
   * They are kept as separate mechanisms deliberately: density outlives a theme, so a consumer can
   * still drive it directly with `useDensity` without going through the editor at all.
   */
  const onSpacingChange = useCallback(
    (value: string) => {
      setSpacing(value);
      setDensity(SPACING_TO_DENSITY[value] ?? "comfortable");
      apply(colorsByMode, radius, value);
    },
    [colorsByMode, radius, apply, setDensity],
  );

  const onElevationChange = useCallback(
    (value: ElevationKey) => {
      setElevation(value);
      apply(colorsByMode, radius, spacing, value, motion);
    },
    [colorsByMode, radius, spacing, motion, apply],
  );

  const onMotionChange = useCallback(
    (value: MotionKey) => {
      setMotion(value);
      apply(colorsByMode, radius, spacing, elevation, value);
    },
    [colorsByMode, radius, spacing, elevation, apply],
  );

  /**
   * Typed text is kept as typed, and applied only when it is valid.
   *
   * The provider throws on a stack that could break out of the declaration, which is correct for a
   * theme written in a file and wrong here — somebody typing `Font (Bold)` would take the page down
   * on the `(`. So the field always shows what was typed, and the theme only receives it once it
   * would survive injection. Invalid text is marked, not swallowed: the value stays visible with
   * `aria-invalid` on the field, rather than silently doing nothing.
   */
  const onCustomFontChange = useCallback(
    (slot: keyof ThemeFonts) => (event: ChangeEvent<HTMLInputElement>) => {
      const typed = event.target.value;
      const next = { ...customFonts, [slot]: typed };
      setCustomFonts(next);

      const applicable = Object.fromEntries(
        Object.entries(next).filter(
          ([, v]) => typeof v === "string" && (v.trim() === "" || isValidFontFamily(v)),
        ),
      );
      apply(colorsByMode, radius, spacing, elevation, motion, typography, applicable);
    },
    [customFonts, colorsByMode, radius, spacing, elevation, motion, typography, apply],
  );

  /** A slot with text that cannot be injected — shown as invalid rather than applied. */
  const invalidFontSlot = useCallback(
    (slot: keyof ThemeFonts): boolean => {
      const v = customFonts[slot];
      return typeof v === "string" && v.trim() !== "" && !isValidFontFamily(v);
    },
    [customFonts],
  );

  const onTypographyChange = useCallback(
    (value: TypographyKey) => {
      setTypography(value);
      apply(colorsByMode, radius, spacing, elevation, motion, value);
    },
    [colorsByMode, radius, spacing, elevation, motion, apply],
  );

  const reset = useCallback(() => {
    setColorsByMode(origin);
    setRadius(DEFAULT_RADIUS);
    setSpacing(DEFAULT_SPACING);
    setDensity(SPACING_TO_DENSITY[DEFAULT_SPACING] ?? "comfortable");
    setElevation("inherit");
    setMotion("inherit");
    setTypography("inherit");
    setCustomFonts({});
    apply(origin, DEFAULT_RADIUS, DEFAULT_SPACING, "inherit", "inherit", "inherit", {});
  }, [origin, apply, setDensity]);

  return (
    <section
      data-slot="theme-editor"
      className={cn("flex flex-col gap-5 rounded-xl border border-border bg-card p-5", className)}
    >
      <header className="flex items-center justify-between gap-3">
        <div>
          <h3 className="font-display text-title-md tracking-tight">{labels.heading}</h3>
          <p className="text-body-sm text-muted-foreground">{labels.subtitle(mode)}</p>
        </div>
        <button
          type="button"
          onClick={reset}
          className={cn(
            "inline-flex h-9 items-center gap-2 rounded-lg border border-border/60 px-3",
            "font-medium text-body-sm transition-colors hover:bg-muted",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          )}
        >
          <RotateCcw className="size-4" aria-hidden="true" />
          {labels.reset}
        </button>
      </header>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.brandSection}
        </legend>
        <label className="flex items-center gap-3 text-body-sm">
          <input
            type="color"
            onChange={onSeedChange}
            aria-label={labels.brandColour}
            className="size-9 shrink-0 cursor-pointer rounded-md border border-border/60 bg-transparent"
          />
          <span className="min-w-0 text-muted-foreground">{labels.brandHint}</span>
        </label>
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.colourSection}
        </legend>
        {/*
          Grouped and collapsed rather than one wall of thirty-three swatches. `<details>` because
          it is a disclosure and the browser already knows how to do one — keyboard, screen reader
          and the open/closed state come free, and none of them survive a hand-rolled version
          intact.
        */}
        {COLOR_GROUPS.map((group) => (
          <details
            key={group.id}
            open={openGroup === group.id}
            onToggle={(event) => {
              if (event.currentTarget.open) setOpenGroup(group.id);
            }}
            className="rounded-lg border border-border/60"
          >
            <summary className="cursor-pointer px-3 py-2 font-medium text-body-sm marker:text-muted-foreground">
              {labels.groups[group.id]}
              <span className="ml-2 font-mono text-label text-muted-foreground">
                {group.tokens.length}
              </span>
            </summary>
            <div className="grid grid-cols-[repeat(auto-fill,minmax(11rem,1fr))] gap-2 px-3 pt-1 pb-3">
              {group.tokens.map((token) => (
                <label key={token} className="flex items-center gap-2 text-body-sm">
                  <input
                    type="color"
                    value={asSwatch(colors[token])}
                    onChange={onColorChange(token)}
                    aria-label={labels.colours[token]}
                    className="size-7 shrink-0 cursor-pointer rounded-md border border-border/60 bg-transparent"
                  />
                  <span className="min-w-0 truncate">{labels.colours[token]}</span>
                </label>
              ))}
            </div>
          </details>
        ))}
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.cornerSection}
        </legend>
        {/*
          Real radio inputs rather than buttons carrying `role="radio"`. The ARIA role would
          describe the behaviour without providing it: a native radio group is one tab stop with
          arrow-key movement between options, which a set of buttons is not, and rebuilding that
          by hand is how a control ends up announcing one thing and doing another.

          The input is visually hidden rather than `display: none`, which would take it out of the
          accessibility tree along with the focus ring.
        */}
        <div className="flex flex-wrap gap-2">
          {RADIUS_VALUES.map((value) => (
            <label
              key={value}
              className={cn(
                "inline-flex h-9 cursor-pointer items-center px-3",
                "font-medium text-body-sm transition-colors",
                "border has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
                radius === value
                  ? "border-primary bg-primary/10 text-primary"
                  : "border-border/60 hover:bg-muted",
              )}
              style={{ borderRadius: value }}
            >
              <input
                type="radio"
                name="theme-editor-radius"
                value={value}
                checked={radius === value}
                onChange={() => {
                  onRadiusChange(value);
                }}
                className="sr-only"
              />
              {labels.corners[value]}
            </label>
          ))}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.densitySection}
        </legend>
        {/*
          One value, and every `p-*`, `gap-*` and `m-*` utility moves with it: they all compile to
          `calc(var(--spacing) * n)`. A whole-UI rhythm control for one custom property.
        */}
        <div className="flex flex-wrap gap-2">
          {SPACING_VALUES.map((value) => (
            <label
              key={value}
              className={cn(
                "inline-flex h-9 cursor-pointer items-center rounded-lg px-3",
                "font-medium text-body-sm transition-colors",
                "border has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
                spacing === value
                  ? "border-primary bg-primary/10 text-primary"
                  : "border-border/60 hover:bg-muted",
              )}
            >
              <input
                type="radio"
                name="theme-editor-spacing"
                value={value}
                checked={spacing === value}
                onChange={() => {
                  onSpacingChange(value);
                }}
                className="sr-only"
              />
              {labels.density[value]}
            </label>
          ))}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.elevationSection}
        </legend>
        <PresetRow
          name="theme-editor-elevation"
          options={Object.keys(ELEVATION_PRESETS) as ElevationKey[]}
          value={elevation}
          labels={labels.elevation}
          onChange={onElevationChange}
        />
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.motionSection}
        </legend>
        <PresetRow
          name="theme-editor-motion"
          options={Object.keys(MOTION_PRESETS) as MotionKey[]}
          value={motion}
          labels={labels.motion}
          onChange={onMotionChange}
        />
      </fieldset>

      <fieldset className="flex flex-col gap-2">
        <legend className="pb-2 font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.typographySection}
        </legend>
        <PresetRow
          name="theme-editor-typography"
          options={Object.keys(TYPOGRAPHY_PRESETS) as TypographyKey[]}
          value={typography}
          labels={labels.typography}
          onChange={onTypographyChange}
        />

        {/*
          The escape hatch. Presets keep the three faces agreeing with each other and cover the
          common case; a company with its own type does not want "Geometric", it wants its own, and
          a design system that cannot express that is one people fork.

          Per slot, so a custom display face can sit over a preset's body and mono. Blank means
          unused — the preset stays in charge until somebody types.
        */}
        <details className="rounded-lg border border-border/60">
          <summary className="cursor-pointer px-3 py-2 font-medium text-body-sm marker:text-muted-foreground">
            {labels.customFont}
          </summary>
          <div className="flex flex-col gap-2 border-border/40 border-t px-3 py-3">
            {(["display", "body", "mono"] as const).map((slot) => (
              <label key={slot} className="flex items-center gap-2 text-body-sm">
                <span className="w-20 shrink-0 font-mono text-label text-muted-foreground uppercase">
                  {labels.fontSlots[slot]}
                </span>
                <input
                  type="text"
                  value={customFonts[slot] ?? ""}
                  onChange={onCustomFontChange(slot)}
                  placeholder={labels.customFontPlaceholder}
                  spellCheck={false}
                  aria-invalid={invalidFontSlot(slot)}
                  className={cn(
                    "min-w-0 flex-1 rounded-md border border-input bg-card px-2 py-1",
                    "font-mono text-code-sm text-foreground",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    invalidFontSlot(slot) && "border-destructive",
                  )}
                />
              </label>
            ))}
            <p className="text-label text-muted-foreground">{labels.customFontHint}</p>
          </div>
        </details>
      </fieldset>

      <ContrastReport findings={findings} labels={labels} />

      {onCommit ? (
        <button
          type="button"
          disabled={!readable && !allowFailing}
          onClick={() => {
            onCommit(build(colorsByMode, radius, spacing, elevation, motion, typography));
          }}
          className={cn(
            "inline-flex h-10 items-center justify-center gap-2 rounded-lg px-4",
            "font-medium text-body-sm transition-colors",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            "disabled:cursor-not-allowed disabled:opacity-50",
            "bg-primary text-primary-foreground hover:bg-primary/90",
          )}
        >
          <Check className="size-4" aria-hidden="true" />
          {readable ? labels.save : labels.saveAnyway(failing.length)}
        </button>
      ) : null}
    </section>
  );
}

/**
 * A row of radios sharing one name.
 *
 * Extracted because elevation, motion and density are the same control three times, and three
 * copies of a native radio group is three chances to forget the shared `name` that makes it one.
 */
function PresetRow<T extends string>({
  name,
  options,
  value,
  labels,
  onChange,
}: {
  name: string;
  options: readonly T[];
  value: T;
  labels: Record<T, string>;
  onChange: (next: T) => void;
}): JSX.Element {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((option) => (
        <label
          key={option}
          className={cn(
            "inline-flex h-9 cursor-pointer items-center rounded-lg px-3",
            "font-medium text-body-sm transition-colors",
            "border has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
            value === option
              ? "border-primary bg-primary/10 text-primary"
              : "border-border/60 hover:bg-muted",
          )}
        >
          <input
            type="radio"
            name={name}
            value={option}
            checked={value === option}
            onChange={() => {
              onChange(option);
            }}
            className="sr-only"
          />
          {labels[option]}
        </label>
      ))}
    </div>
  );
}

/**
 * The audit, shown in full rather than as a pass/fail badge.
 *
 * Someone dragging a colour wants to watch the ratio approach 4.5, not discover at the end that it
 * never got there. Failures are listed first because they are what needs action.
 */
function ContrastReport({
  findings,
  labels,
}: {
  findings: ContrastFinding[];
  labels: ThemeEditorLabels;
}): JSX.Element {
  const failing = findings.filter((f) => !f.passes);
  const ordered = [...failing, ...findings.filter((f) => f.passes)];

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <span className="font-mono text-label text-muted-foreground uppercase tracking-wider">
          {labels.contrastSection}
        </span>
        {failing.length > 0 ? (
          <span className="inline-flex items-center gap-1 rounded-full bg-destructive/15 px-2 py-0.5 font-mono text-destructive text-label uppercase">
            <AlertTriangle className="size-3" aria-hidden="true" />
            {labels.belowMinimum(failing.length)}
          </span>
        ) : (
          <span className="inline-flex items-center gap-1 rounded-full bg-success/15 px-2 py-0.5 font-mono text-label text-success uppercase">
            <Check className="size-3" aria-hidden="true" />
            {labels.allPass}
          </span>
        )}
      </div>

      {/* A live region, because the number changes as a colour is dragged and a screen-reader user
          would otherwise get no feedback at all from this panel. */}
      <ul aria-live="polite" className="flex flex-col gap-1">
        {ordered.map((finding) => (
          <li
            key={`${finding.foreground}-${finding.background}`}
            className="flex items-center justify-between gap-3 font-mono text-label"
          >
            <span className="min-w-0 truncate text-muted-foreground">
              {finding.foreground} on {finding.background}
            </span>
            <span
              className={cn(
                "shrink-0 tabular-nums",
                finding.passes ? "text-success" : "text-destructive",
              )}
            >
              {finding.ratio === null
                ? labels.unreadable
                : `${finding.ratio.toFixed(2)}:1 · ${labels.needs(finding.minimum)}`}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * A preset, with anything typed overriding it slot by slot.
 *
 * Returns `undefined` when there is nothing to say, so `inherit` with no custom entry keeps
 * emitting nothing and `tokens.css` holds its own faces. Blank strings are dropped rather than
 * emitted: an empty `font-family` is a declaration that erases the face instead of leaving it.
 */
function mergeFonts(
  preset: Readonly<Partial<ThemeFonts>> | undefined,
  custom: Partial<ThemeFonts>,
): Partial<ThemeFonts> | undefined {
  const typed = Object.fromEntries(
    Object.entries(custom).filter(([, v]) => typeof v === "string" && v.trim() !== ""),
  );
  if (!preset && Object.keys(typed).length === 0) return undefined;
  return { ...preset, ...typed };
}

/** One slider value becomes the whole radius scale, kept in proportion. */
function buildRadius(base: string): RadiusScale {
  const px = Number.parseFloat(base);
  if (!Number.isFinite(px)) return { DEFAULT: base };
  const step = (factor: number): string => `${String(Math.round(px * factor))}px`;

  return {
    none: "0px",
    sm: step(0.3),
    md: step(0.5),
    lg: step(0.75),
    xl: base,
    "2xl": step(1.4),
    full: "9999px",
    DEFAULT: base,
  };
}

export { DEFAULT_LABELS, ThemeEditor, buildRadius };
export type { ThemeMode };

/**
 * ThemeScript — inline `<script>` for SSR-safe theme initialization.
 *
 * Renders a synchronous script that runs BEFORE React hydration. It resolves the mode the way
 * `ThemeProvider` does — the persisted choice first, then the OS `prefers-color-scheme` when
 * `respectSystemMode` is on, then the default — and writes `data-theme` / `data-mode` /
 * `data-density` on the root element, plus the `.dark` class when the mode is dark.
 *
 * Resolving it the SAME way is the whole point. The provider settles the mode again after
 * hydration; if the two disagree the page paints once and repaints, which is precisely the flash
 * this component exists to remove. Pass it the same `defaultTheme`, `defaultMode`, `storageKey`
 * and `respectSystemMode` you pass the provider — `theme-boot-agreement.test.tsx` holds them
 * together across the matrix.
 *
 * Place this in `<head>` ABOVE `<body>`. The component does not need to live
 * inside `<ThemeProvider>`.
 *
 * Security: every interpolated value is passed through `safe()`, which both
 * `JSON.stringify`s the value AND escapes `<` to `<`. The `<` escape is
 * REQUIRED because `JSON.stringify` alone does NOT escape `/`, so a payload
 * like `"</script><script>alert(1)</script>"` would otherwise break out of
 * the inline `<script>` tag even though it stays inside a JS string literal.
 * (The browser tokenizes `</script>` at the HTML layer before JS parses.)
 *
 * Example (Next.js App Router): see wiki/design-system/themes.md → SSR section.
 * Pass `defaultTheme` and `defaultMode` to align with the consumer's
 * preferred initial state. Always wrap the root in `<html
 * suppressHydrationWarning>` to silence the expected one-render diff.
 */
import type { JSX } from "react";
import type { ThemeMode } from "@/themes/types";

interface ThemeScriptProps {
  /** Theme name to apply when no persisted value exists. Default `"violet-forge"`. */
  defaultTheme?: string;
  /** Mode to apply when no persisted value exists. Default `"dark"`. */
  defaultMode?: ThemeMode;
  /**
   * Density to apply when no persisted value exists. Default `"comfortable"`.
   * Mirrors `ThemeProvider`'s `defaultDensity` so the inline-script and
   * the React provider agree on the SSR-default density (and the
   * `data-density` attribute set by this script matches what
   * `ThemeProvider` promotes via its post-mount hydration effect).
   */
  defaultDensity?: "compact" | "comfortable" | "spacious";
  /**
   * localStorage namespace. Must match the `storageKey` passed to
   * `<ThemeProvider>`. Default `"theo-ui:theme"`. Pass `null` to disable
   * persistence reads (the script will always apply defaults).
   */
  storageKey?: string | null;
  /**
   * Follow the OS `prefers-color-scheme` when nothing is stored. Default `true`.
   *
   * Must match the value passed to `<ThemeProvider>`, whose default is also `true`. When the two
   * disagree, the script applies one mode and the provider applies the other the moment React
   * hydrates — the page repaints, which is the flash this component exists to remove.
   */
  respectSystemMode?: boolean;
  /**
   * CSP nonce for the inline `<script>`.
   *
   * A nonce-based `script-src` blocks an unstamped inline script outright, and this one has to run
   * before the first paint or it is worthless. Pass the per-request nonce here on any app that
   * serves one.
   */
  nonce?: string;
}

/**
 * Encode a value for safe embedding inside an inline `<script>` block.
 *
 * `JSON.stringify` does NOT escape `/` by default, so `"</script>"` survives
 * as the literal three-character sequence inside the resulting string. When
 * that string is then rendered inside `<script>...</script>`, the browser's
 * HTML tokenizer sees `</script>` and ends the script tag — regardless of
 * whether the JS parser would have kept it inside a string. Escaping `<` to
 * its Unicode escape `<` preserves JS semantics (the JS parser still
 * resolves the escape to `<`) while making the HTML tokenizer happy.
 *
 * Reference: OWASP "JSON-in-script" guidance; React's own server-renderer
 * applies the same escape for inline JSON.
 */
function safe(value: unknown): string {
  return JSON.stringify(value).replace(/</g, "\\u003c");
}

function buildScript(
  defaultTheme: string,
  defaultMode: ThemeMode,
  defaultDensity: "compact" | "comfortable" | "spacious",
  storageKey: string | null,
  respectSystemMode: boolean,
): string {
  const k = safe(storageKey);
  const t = safe(defaultTheme);
  const m = safe(defaultMode);
  const dn = safe(defaultDensity);
  const sys = respectSystemMode ? "1" : "0";
  // Mirrors ThemeProvider's own resolution, branch for branch: a stored value only counts when it
  // is one of the valid literals, the OS signal decides when nothing is stored and
  // `respectSystemMode` is on, and the default is the last resort — including when the engine has
  // no `matchMedia`, which is exactly where the provider's effect bails out.
  return `(function(){try{var k=${k};var d=document.documentElement;var t=null;var m=null;var dn=null;if(k){t=localStorage.getItem(k+":name");m=localStorage.getItem(k+":mode");dn=localStorage.getItem(k+":density");}if(m!=="dark"&&m!=="light"){m=(${sys}&&window.matchMedia)?(window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"):${m};}if(dn!=="compact"&&dn!=="comfortable"&&dn!=="spacious"){dn=${dn};}d.setAttribute("data-theme",t||${t});d.setAttribute("data-mode",m);d.setAttribute("data-density",dn);d.classList.toggle("dark",m==="dark");}catch(e){}})();`;
}

function ThemeScript({
  defaultTheme = "violet-forge",
  defaultMode = "dark",
  defaultDensity = "comfortable",
  storageKey = "theo-ui:theme",
  respectSystemMode = true,
  nonce,
}: ThemeScriptProps): JSX.Element {
  const code = buildScript(
    defaultTheme,
    defaultMode,
    defaultDensity,
    storageKey,
    respectSystemMode,
  );
  return (
    <script
      nonce={nonce}
      suppressHydrationWarning
      // biome-ignore lint/security/noDangerouslySetInnerHtml: payload is JSON.stringify-encoded literals (no user input); intentional for SSR theme bootstrap before React hydrates
      dangerouslySetInnerHTML={{ __html: code }}
    />
  );
}

export { ThemeScript };

"use client";

import { useCallback, useEffect, useState } from "react";

import { isDev } from "@/lib/env";
import { useTheme } from "@/themes/theme-provider";
import type { Theme } from "@/themes/types";

/**
 * Keep a theme somebody built across reloads.
 *
 * `ThemeProvider` already persists WHICH theme is active and in which mode. It cannot persist a
 * theme that does not exist in code: a palette assembled in the editor lives only in the React
 * tree, so a reload took it away and the person built it again. That is the gap between a demo and
 * a feature.
 *
 * Deliberately a hook rather than something the editor does by itself. `ThemeEditor` hands back a
 * `Theme` and has no opinion about where it lives — some consumers want `localStorage`, some want a
 * row in their database, some want it in a URL to share. Baking storage into the component would
 * make the first case free and the other two a fork.
 *
 * WHAT IT DOES NOT DO: validate the stored object beyond its shape. `ThemeProvider` already
 * rejects unsafe values at injection time, so a tampered entry produces a dev-time throw there
 * rather than arbitrary CSS here — the check that matters is the one that runs on the way in.
 */

/** Shape check, not a schema. Enough to tell a theme from a truncated write or an old format. */
function looksLikeTheme(value: unknown): value is Theme {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<Theme>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.label === "string" &&
    typeof candidate.light === "object" &&
    typeof candidate.dark === "object" &&
    typeof candidate.fonts === "object"
  );
}

function warn(message: string, error: unknown): void {
  if (!isDev()) return;
  // biome-ignore lint/suspicious/noConsole: dev-only diagnostic for storage failures
  console.warn(`[@theokit/ui] ${message}`, error);
}

/**
 * Read a stored theme synchronously, for passing to `ThemeProvider` on the way in.
 *
 * This exists because registering a theme from an effect is too late. `ThemeProvider` resolves the
 * active theme NAME in its own effect, from its own storage key, and a name it does not have a
 * theme for falls back to the default — so a custom theme registered after that resolution is in
 * the registry and not applied. Measured: after a reload the editor's saved palette was in
 * `localStorage`, the "forget it" affordance appeared, and `data-theme` was the built-in one.
 *
 * Passing the result into `themes` fixes the ordering rather than racing it:
 *
 *   const stored = readStoredTheme("my-app:theme")
 *   <ThemeProvider themes={stored ? [base, stored] : [base]} defaultTheme={base.name}>
 *
 * Returns `undefined` on a server, where there is no storage to read — the client re-renders with
 * the real value, which is the same trade every theme system makes for this.
 */
export function readStoredTheme(storageKey = "theo-ui:theme:custom"): Theme | undefined {
  if (typeof window === "undefined") return undefined;

  let raw: string | null = null;
  try {
    raw = window.localStorage.getItem(storageKey);
  } catch (error) {
    warn(`could not read stored theme (${storageKey})`, error);
    return undefined;
  }
  if (raw === null) return undefined;

  try {
    const parsed: unknown = JSON.parse(raw);
    if (looksLikeTheme(parsed)) return parsed;
    warn(`stored theme has the wrong shape and was ignored (${storageKey})`, parsed);
  } catch (error) {
    warn(`stored theme is not valid JSON (${storageKey})`, error);
  }
  return undefined;
}

export interface StoredThemeApi {
  /** The theme read from storage on mount, or `undefined` if there was none. */
  stored: Theme | undefined;
  /** Persist a theme and make it active. */
  save: (theme: Theme) => void;
  /** Forget the stored theme. Does not change what is currently applied. */
  clear: () => void;
}

/**
 * Restore a saved theme on mount, and save new ones.
 *
 * The restore runs in an effect rather than during render because `localStorage` does not exist on
 * a server, and reading it while rendering makes the first client paint disagree with the markup
 * that was sent — the flash every theme system has to avoid.
 */
export function useStoredTheme(storageKey = "theo-ui:theme:custom"): StoredThemeApi {
  const { registerTheme, setTheme } = useTheme();
  const [stored, setStored] = useState<Theme | undefined>(undefined);

  useEffect(() => {
    const theme = readStoredTheme(storageKey);
    if (!theme) return;

    setStored(theme);
    // Registering here still matters for the case where the consumer did NOT pass the theme in via
    // `themes` — it makes the theme available even though the name may already have resolved
    // elsewhere. `readStoredTheme` at mount is what makes it actually apply.
    registerTheme(theme);
    setTheme(theme.name);
  }, [storageKey, registerTheme, setTheme]);

  const save = useCallback(
    (theme: Theme) => {
      setStored(theme);
      registerTheme(theme);
      setTheme(theme.name);

      if (typeof window === "undefined") return;
      try {
        window.localStorage.setItem(storageKey, JSON.stringify(theme));
      } catch (error) {
        // The theme is applied either way. Failing to persist is worth a warning, not a broken UI.
        warn(`could not persist theme (${storageKey})`, error);
      }
    },
    [storageKey, registerTheme, setTheme],
  );

  const clear = useCallback(() => {
    setStored(undefined);
    if (typeof window === "undefined") return;
    try {
      window.localStorage.removeItem(storageKey);
    } catch (error) {
      warn(`could not clear stored theme (${storageKey})`, error);
    }
  }, [storageKey]);

  return { stored, save, clear };
}

